--
-- TOC entry 7246 (class 1259 OID 158996012)
-- Name: fm005r_view; Type: VIEW; Schema: cjams; Owner: cjams_prod_admin
--

CREATE VIEW fm005r_view AS
 SELECT tb_main.fiscal_category_cd,
    sum(tb_main.current_payments) AS current_payments,
    sum(tb_main.current_adjustments) AS current_adjustments,
    sum(tb_main.current_receivalbles) AS current_receivalbles,
    sum(tb_main.net_current_expenditures) AS net_current_expenditures,
    sum(tb_main.federal_amt) AS federal_amt,
    sum(tb_main.state_amt) AS state_amt,
    sum(COALESCE(tb_main.client_count, (0)::bigint)) AS client_count,
    tb_main.county,
    tb_main.payment_start_dt,
    tb_main.payment_end_dt
   FROM ( SELECT main.fiscal_category_cd,
            main.current_payments,
            main.current_adjustments,
            main.current_receivalbles,
            ((main.current_payments + main.current_adjustments) - main.current_receivalbles) AS net_current_expenditures,
            main.federal_amt,
            main.state_amt,
            COALESCE(main.client_count, (0)::bigint) AS client_count,
            f_plvalue(main.county_cd, 104) AS county,
            main.payment_start_dt,
            main.payment_end_dt
           FROM ( SELECT tb_fiscal_category_master.fiscal_category_cd,
                    sum(COALESCE(aa.final_amount_no, (0)::numeric)) AS current_payments,
                    0 AS current_adjustments,
                    0 AS current_receivalbles,
                    0 AS federal_amt,
                    0 AS state_amt,
                    0 AS client_count,
                    aa.county_cd,
                    aa.payment_start_dt,
                    aa.payment_end_dt
                   FROM (tb_fiscal_category_master
                     LEFT JOIN ( SELECT pd.final_amount_no,
                            pd.final_fiscal_category_cd,
                            pd.county_cd,
                            ph.payment_start_dt,
                            ph.payment_end_dt
                           FROM (tb_payment_detail pd
                             FULL JOIN tb_payment_header ph ON ((pd.payment_id = ph.payment_id)))
                          WHERE (pd.payment_id IN ( SELECT ph_1.payment_id
                                   FROM tb_payment_header ph_1,
                                    tb_payment_status ps
                                  WHERE ((ph_1.payment_id = ps.payment_id) AND ((ph_1.payment_type_cd)::text = ANY (ARRAY[('4'::character varying)::text, ('6'::character varying)::text, ('7'::character varying)::text, ('5689'::character varying)::text, ('5989'::character varying)::text])) AND ((ps.payment_status_cd)::text = '1636'::text))))) aa ON ((tb_fiscal_category_master.fiscal_category_cd = aa.final_fiscal_category_cd)))
                  WHERE (tb_fiscal_category_master.delete_sw = 'N'::bpchar)
                  GROUP BY tb_fiscal_category_master.fiscal_category_cd, aa.county_cd, aa.payment_start_dt, aa.payment_end_dt
                UNION
                 SELECT tb_fiscal_category_master.fiscal_category_cd,
                    0 AS current_payments,
                    sum(COALESCE(aa.final_amount_no, (0)::numeric)) AS current_adjustments,
                    0 AS current_receivalbles,
                    0 AS federal_amt,
                    0 AS state_amt,
                    0 AS client_count,
                    aa.county_cd,
                    aa.payment_start_dt,
                    aa.payment_end_dt
                   FROM (tb_fiscal_category_master
                     LEFT JOIN ( SELECT pd.final_amount_no,
                            pd.final_fiscal_category_cd,
                            pd.county_cd,
                            ph.payment_start_dt,
                            ph.payment_end_dt
                           FROM (tb_payment_detail pd
                             FULL JOIN tb_payment_header ph ON ((pd.payment_id = ph.payment_id)))
                          WHERE (pd.payment_id IN ( SELECT ph_1.payment_id
                                   FROM tb_payment_header ph_1,
                                    tb_payment_status ps
                                  WHERE (((ph_1.payment_id = ps.payment_id) AND ((ph_1.payment_type_cd)::text = '3294'::text)) OR ((ph_1.payment_end_dt IS NULL) AND ((ps.payment_status_cd)::text = '1636'::text)))))) aa ON ((tb_fiscal_category_master.fiscal_category_cd = aa.final_fiscal_category_cd)))
                  WHERE (tb_fiscal_category_master.delete_sw = 'N'::bpchar)
                  GROUP BY tb_fiscal_category_master.fiscal_category_cd, aa.county_cd, aa.payment_start_dt, aa.payment_end_dt
                UNION
                 SELECT tb_fiscal_category_master.fiscal_category_cd,
                    0 AS current_payments,
                    0 AS current_adjustments,
                    sum(COALESCE(aa.receivable_amt, (0)::numeric)) AS current_receivalbles,
                    0 AS federal_amt,
                    0 AS state_amt,
                    0 AS client_count,
                    aa.county_cd,
                    aa.receipt_dt,
                    aa.offset_dt
                   FROM (tb_fiscal_category_master
                     LEFT JOIN ( SELECT pd.final_fiscal_category_cd,
                            COALESCE(pr.payment_amount_no, (0)::numeric) AS receivable_amt,
                            pd.county_cd,
                            pr.receipt_dt,
                            ro.offset_dt
                           FROM tb_receivable_liquidation rl,
                            tb_payment_receipt pr,
                            tb_receivable_detail rd,
                            tb_payment_detail pd,
                            tb_receivable_offset ro
                          WHERE ((rd.receivable_detail_id = rl.receivable_detail_id) AND (pd.payment_detail_id = rd.payment_detail_id) AND (pr.receipt_id = rl.receipt_id))
                        UNION ALL
                         SELECT pd.final_fiscal_category_cd,
                            COALESCE(ro.offset_amount_no, (0)::numeric) AS receivable_amt,
                            pd.county_cd,
                            pr.receipt_dt,
                            ro.offset_dt
                           FROM tb_receivable_liquidation rl,
                            tb_receivable_offset ro,
                            tb_payment_receipt pr,
                            tb_receivable_detail rd,
                            tb_payment_detail pd
                          WHERE ((rd.receivable_detail_id = rl.receivable_detail_id) AND (pd.payment_detail_id = rd.payment_detail_id) AND (rl.offset_id = ro.offset_id))) aa ON ((tb_fiscal_category_master.fiscal_category_cd = aa.final_fiscal_category_cd)))
                  WHERE (tb_fiscal_category_master.delete_sw = 'N'::bpchar)
                  GROUP BY tb_fiscal_category_master.fiscal_category_cd, aa.county_cd, aa.receipt_dt, aa.offset_dt
                UNION
                 SELECT tb_fiscal_category_master.fiscal_category_cd,
                    0 AS current_payments,
                    0 AS current_adjustments,
                    0 AS current_receivalbles,
                    sum(COALESCE(aa.funding_amount_no, (0)::numeric)) AS federal_amt,
                    0 AS state_amt,
                    0 AS client_count,
                    aa.county_cd,
                    aa.payment_start_dt,
                    aa.payment_end_dt
                   FROM (tb_fiscal_category_master
                     LEFT JOIN ( SELECT tb_payment_fund_allocation.funding_amount_no,
                            tb_payment_detail.final_fiscal_category_cd,
                            tb_payment_detail.county_cd,
                            ph.payment_start_dt,
                            ph.payment_end_dt
                           FROM ((tb_payment_detail
                             LEFT JOIN tb_payment_fund_allocation ON (((tb_payment_detail.payment_detail_id = tb_payment_fund_allocation.payment_detail_id) AND ((tb_payment_fund_allocation.funding_source_cd)::text = '4894'::text))))
                             FULL JOIN tb_payment_header ph ON ((ph.payment_id = tb_payment_detail.payment_id)))
                          WHERE (tb_payment_detail.payment_id IN ( SELECT ph_1.payment_id
                                   FROM tb_payment_header ph_1,
                                    tb_payment_status ps
                                  WHERE ((ph_1.payment_id = ps.payment_id) OR ((ph_1.payment_end_dt IS NULL) AND ((ps.payment_status_cd)::text = '1636'::text)))))) aa ON ((tb_fiscal_category_master.fiscal_category_cd = aa.final_fiscal_category_cd)))
                  WHERE (tb_fiscal_category_master.delete_sw = 'N'::bpchar)
                  GROUP BY tb_fiscal_category_master.fiscal_category_cd, aa.county_cd, aa.payment_start_dt, aa.payment_end_dt
                UNION
                 SELECT tb_fiscal_category_master.fiscal_category_cd,
                    0 AS current_payments,
                    0 AS current_adjustments,
                    0 AS current_receivalbles,
                    0 AS federal_amt,
                    sum(COALESCE(aa.funding_amount_no, (0)::numeric)) AS state_amt,
                    0 AS client_count,
                    aa.county_cd,
                    aa.payment_end_dt,
                    aa.payment_start_dt
                   FROM (tb_fiscal_category_master
                     LEFT JOIN ( SELECT tb_payment_fund_allocation.funding_amount_no,
                            tb_payment_detail.final_fiscal_category_cd,
                            tb_payment_detail.county_cd,
                            ph.payment_end_dt,
                            ph.payment_start_dt
                           FROM ((tb_payment_detail
                             LEFT JOIN tb_payment_fund_allocation ON (((tb_payment_detail.payment_detail_id = tb_payment_fund_allocation.payment_detail_id) AND ((tb_payment_fund_allocation.funding_source_cd)::text = '4895'::text))))
                             FULL JOIN tb_payment_header ph ON ((ph.payment_id = tb_payment_detail.payment_id)))
                          WHERE (tb_payment_detail.payment_id IN ( SELECT ph_1.payment_id
                                   FROM tb_payment_header ph_1,
                                    tb_payment_status ps
                                  WHERE (((ph_1.payment_id = ps.payment_id) AND ((ph_1.payment_type_cd)::text = '3294'::text)) OR ((ph_1.payment_end_dt IS NULL) AND ((ps.payment_status_cd)::text = '1636'::text)))))) aa ON ((tb_fiscal_category_master.fiscal_category_cd = aa.final_fiscal_category_cd)))
                  WHERE (tb_fiscal_category_master.delete_sw = 'N'::bpchar)
                  GROUP BY tb_fiscal_category_master.fiscal_category_cd, aa.county_cd, aa.payment_end_dt, aa.payment_start_dt
                UNION
                 SELECT tb_fiscal_category_master.fiscal_category_cd,
                    0 AS current_payments,
                    0 AS current_adjustments,
                    0 AS current_receivalbles,
                    0 AS federal_amt,
                    0 AS state_amt,
                    aa.client_count,
                    aa.county_cd,
                    aa.payment_start_dt,
                    aa.payment_end_dt
                   FROM (tb_fiscal_category_master
                     LEFT JOIN ( SELECT count(DISTINCT tb_payment_detail.client_id) AS client_count,
                            tb_payment_detail.final_fiscal_category_cd,
                            tb_payment_detail.county_cd,
                            ph.payment_start_dt,
                            ph.payment_end_dt
                           FROM (tb_payment_detail
                             FULL JOIN tb_payment_header ph ON ((ph.payment_id = tb_payment_detail.payment_id)))
                          WHERE ((tb_payment_detail.final_service_id IS NOT NULL) AND (tb_payment_detail.payment_id IN ( SELECT ph_1.payment_id
                                   FROM tb_payment_header ph_1,
                                    tb_payment_status ps
                                  WHERE ((ph_1.payment_id = ps.payment_id) OR ((ph_1.payment_end_dt IS NULL) AND ((ps.payment_status_cd)::text = '1636'::text))))))
                          GROUP BY tb_payment_detail.final_fiscal_category_cd, tb_payment_detail.county_cd, ph.payment_start_dt, ph.payment_end_dt) aa ON ((tb_fiscal_category_master.fiscal_category_cd = aa.final_fiscal_category_cd)))
                  WHERE (tb_fiscal_category_master.delete_sw = 'N'::bpchar)) main
          ORDER BY main.fiscal_category_cd, (f_plvalue(main.county_cd, 104))) tb_main
  GROUP BY tb_main.fiscal_category_cd, tb_main.county, tb_main.payment_start_dt, tb_main.payment_end_dt;


ALTER TABLE fm005r_view OWNER TO cjams_prod_admin;

