--
-- TOC entry 7252 (class 1259 OID 158996101)
-- Name: fm100r_view; Type: VIEW; Schema: cjams; Owner: cjams_prod_admin
--

CREATE VIEW fm100r_view AS
 SELECT DISTINCT pdi.fmis_payment_detail_record_id,
    pdi.current_document_nbr_cd,
    ('00'::text || (row_number() OVER (PARTITION BY pdi.batch_no ORDER BY pdi.current_document_nbr_cd, pdi.fmis_payment_detail_record_id))::text) AS current_document_nbr_suffix,
    pdi.batch_no,
    pdi.invoice_nbr,
    pdi.vendor_tax_type_cd,
    pdi.vendor_mail_code_tx,
    pdi.payment_dis_type_cd,
    pdi.transaction_amt,
    pdi.reverse_ind,
    ph.payment_id,
    ph.payee_nm,
    rtrim((f_add('TB_PAYMENT_HEADER'::character varying, 'PAYMENT_ID'::character varying, ph.payment_id, ph.adr_type_cd, ''::character varying))::text) AS address,
    (phi.batch_dt)::character varying AS batch_dt,
    ph.adr_format_cd,
    ph.offset_amount_no
   FROM ((tb_fmis_payment_detail_interface pdi
     LEFT JOIN tb_payment_header ph ON (((pdi.invoice_nbr)::integer = ph.payment_id)))
     JOIN tb_fmis_payment_header_interface phi ON (((pdi.batch_no)::text = (phi.batch_no)::text)));


