    date(afs.create_ts) AS create_ts,
        CASE
            WHEN ((afs.ldss_nm)::text = '01'::text) THEN 'Allegany (01)'::character varying
            WHEN ((afs.ldss_nm)::text = '02'::text) THEN 'Anne Arundel (02)'::character varying
            WHEN ((afs.ldss_nm)::text = '03'::text) THEN 'Baltimore County (03)'::character varying
            WHEN ((afs.ldss_nm)::text = '04'::text) THEN 'Calvert (04)'::character varying
            WHEN ((afs.ldss_nm)::text = '05'::text) THEN 'Caroline (05)'::character varying
            WHEN ((afs.ldss_nm)::text = '06'::text) THEN 'Carroll (06)'::character varying
            WHEN ((afs.ldss_nm)::text = '07'::text) THEN 'Cecil (07)'::character varying
            WHEN ((afs.ldss_nm)::text = '08'::text) THEN 'Charles (08)'::character varying
            WHEN ((afs.ldss_nm)::text = '09'::text) THEN 'Dorchester (09)'::character varying
            WHEN ((afs.ldss_nm)::text = '10'::text) THEN 'Frederick (10)'::character varying
            WHEN ((afs.ldss_nm)::text = '11'::text) THEN 'Garrett (11)'::character varying
            WHEN ((afs.ldss_nm)::text = '12'::text) THEN 'Harford (12)'::character varying
            WHEN ((afs.ldss_nm)::text = '13'::text) THEN 'Howard (13)'::character varying
            WHEN ((afs.ldss_nm)::text = '14'::text) THEN 'Kent (14)'::character varying
            WHEN ((afs.ldss_nm)::text = '15'::text) THEN 'Montgomery (15)'::character varying
            WHEN ((afs.ldss_nm)::text = '16'::text) THEN 'Prince Georges (16)'::character varying
            WHEN ((afs.ldss_nm)::text = '17'::text) THEN 'Queen Annes (17)'::character varying
            WHEN ((afs.ldss_nm)::text = '18'::text) THEN 'St. Marys (18)'::character varying
            WHEN ((afs.ldss_nm)::text = '19'::text) THEN 'Somerset (19)'::character varying
            WHEN ((afs.ldss_nm)::text = '20'::text) THEN 'Talbot (20)'::character varying
            WHEN ((afs.ldss_nm)::text = '21'::text) THEN 'Washington (21)'::character varying
            WHEN ((afs.ldss_nm)::text = '22'::text) THEN 'Wicomico (22)'::character varying
