--
-- TOC entry 7262 (class 1259 OID 158996162)
-- Name: fm120r_draft_private_view; Type: VIEW; Schema: cjams; Owner: cjams_prod_admin
--

CREATE VIEW fm120r_draft_private_view AS
 SELECT DISTINCT p.payment_id,
    p.provider_id,
    f_ename('2953'::character varying, p.provider_id, ''::character varying) AS provider_name,
    aa.cc AS distinct_children_count,
    ( SELECT sum(COALESCE(tb_payment_detail.draft_amount_no, (0)::numeric)) AS sum
           FROM tb_payment_detail
          WHERE ((tb_payment_detail.payment_id = p.payment_id) AND (tb_payment_detail.delete_sw = 'N'::bpchar) AND (tb_payment_detail.draft_service_id IS NOT NULL))) AS sum_amount_no_gross,
    ( SELECT tb_com.comment
           FROM ( SELECT (sum(tb1_group.num_pages) + 1) AS pages,
                        CASE
                            WHEN ((sum(tb1_group.num_pages) + 1) <= 12) THEN 'TRI-FOLD'::text
                            WHEN (((sum(tb1_group.num_pages) + 1) > 12) AND ((sum(tb1_group.num_pages) + 1) <= 24)) THEN 'BI-FOLD'::text
                            ELSE 'NO-FOLD'::text
                        END AS comment,
                    tb1_group.payment_id
                   FROM ( SELECT count(tb_main.client_id) AS child_count,
                            COALESCE(sum(tb_main.draft_amount_no), (0)::numeric) AS gross_amount,
                            f_rpt_num_pages(count(tb_main.client_id)) AS num_pages,
                            tb_main.payment_id,
                            tb_main.program_nm
                           FROM ( SELECT d.client_id,
                                    d.draft_amount_no,
                                    d.payment_id,
                                    ( SELECT program.programname AS program_nm
   FROM program
  WHERE ((program.old_id)::integer IN ( SELECT tb_placement_delete.contract_program_id
     FROM tb_placement_delete
    WHERE (tb_placement_delete.placement_id = d.placement_id)))) AS program_nm
                                   FROM tb_payment_detail d
                                  WHERE (d.payment_id IN ( SELECT ph.payment_id
   FROM tb_payment_header ph,
    tb_payment_detail pd
  WHERE ((ph.payment_id = pd.payment_id) AND ((ph.payment_type_cd)::text = '6'::text) AND (ph.payment_start_dt = p.payment_start_dt) AND (ph.delete_sw = 'N'::bpchar) AND (pd.delete_sw = 'N'::bpchar) AND (pd.draft_service_id IS NOT NULL) AND ((f_prvpcklst_cat(ph.provider_id, 'PLACEMENT'::character varying))::text <> '1783'::text))))) tb_main
                          GROUP BY tb_main.program_nm, tb_main.payment_id) tb1_group
                  GROUP BY tb1_group.payment_id) tb_com
          WHERE (tb_com.payment_id = p.payment_id)) AS comment,
    p.payment_start_dt
   FROM tb_payment_header p,
    ( SELECT ab.payment_id,
            sum(ab.cc) AS cc
           FROM ( SELECT a.payment_id,
                    count(DISTINCT a.client_id) AS cc,
                    a.program_nm
                   FROM ( SELECT ph.payment_id,
                            pd.client_id,
                            ( SELECT program.programname AS program_nm
                                   FROM program
                                  WHERE ((program.old_id)::integer IN ( SELECT tb_placement_delete.contract_program_id
   FROM tb_placement_delete
  WHERE (tb_placement_delete.placement_id = pd.placement_id)))) AS program_nm
                           FROM tb_payment_header ph,
                            tb_payment_detail pd
                          WHERE ((ph.payment_id = pd.payment_id) AND ((ph.payment_type_cd)::text = '6'::text) AND (ph.delete_sw = 'N'::bpchar) AND (pd.delete_sw = 'N'::bpchar) AND (pd.draft_service_id IS NOT NULL) AND ((f_prvpcklst_cat(ph.provider_id, 'PLACEMENT'::character varying))::text <> '1783'::text))) a
                  GROUP BY a.payment_id, a.program_nm) ab
          GROUP BY ab.payment_id) aa
  WHERE (p.payment_id = aa.payment_id)
  ORDER BY p.payment_id, p.provider_id;


ALTER TABLE fm120r_draft_private_view OWNER TO cjams_prod_admin;

