                            WHEN (((sum(tb1_group.num_pages) + 1) > 12) AND ((sum(tb1_group.num_pages) + 1) <= 24)) THEN 'BI-FOLD'::text
                            ELSE 'NO-FOLD'::text
                        END AS comment,
                    tb1_group.payment_id
                   FROM ( SELECT count(tb_main.client_id) AS child_count,
                            COALESCE(sum(tb_main.draft_amount_no), (0)::numeric) AS gross_amount,
