--
-- TOC entry 7267 (class 1259 OID 158996192)
-- Name: fm120r_mps_private_count_view; Type: VIEW; Schema: cjams; Owner: cjams_prod_admin
--

CREATE VIEW fm120r_mps_private_count_view AS
 SELECT tb_main.program_nm,
    COALESCE(count(DISTINCT tb_main.client_id), (0)::bigint) AS child_count,
    tb_main.payment_id,
    tb_main.provider_id,
    tb_main.payment_start_dt,
    COALESCE(sum(tb_main.draft_amount_no), (0)::numeric) AS gross_amount,
    ( SELECT tb1_com.comment
           FROM ( SELECT (sum(tb1_group.num_pages) + 1) AS pages,
                        CASE
                            WHEN ((sum(tb1_group.num_pages) + 1) <= 12) THEN 'TRI-FOLD'::text
                            WHEN (((sum(tb1_group.num_pages) + 1) > 12) AND ((sum(tb1_group.num_pages) + 1) <= 24)) THEN 'BI-FOLD'::text
                            ELSE 'NO-FOLD'::text
                        END AS comment
                   FROM ( SELECT tb_main_1.program_nm,
                            count(tb_main_1.client_id) AS child_count,
                            f_rpt_num_pages(count(tb_main_1.client_id)) AS num_pages
                           FROM ( SELECT ( SELECT tb_contract_program.program_nm
   FROM prov.tb_contract_program
  WHERE (tb_contract_program.contract_id = ( SELECT DISTINCT tb_placement_delete.contract_program_id
     FROM tb_placement_delete
    WHERE (tb_placement_delete.placement_id = d.placement_id)))) AS program_nm,
                                    d.client_id,
                                    d.draft_amount_no
                                   FROM tb_payment_detail d
                                  WHERE ((d.delete_sw = 'N'::bpchar) AND (d.payment_id IN ( SELECT ph.payment_id
   FROM (tb_payment_header ph
     JOIN prov.tb_provider p ON (((ph.provider_id = p.provider_id) AND (ph.delete_sw = 'N'::bpchar))))
  WHERE (ph.payment_id IN ( SELECT h.payment_id
     FROM (tb_payment_header h
       JOIN tb_payment_detail pd ON ((h.payment_id = pd.payment_id)))
    WHERE (((h.payment_type_cd)::text = '6'::text) AND (h.delete_sw = 'N'::bpchar) AND (pd.delete_sw = 'N'::bpchar) AND ((f_prvpcklst_cat(h.provider_id, 'PLACEMENT'::character varying))::text = ANY (ARRAY[('1782'::character varying)::text, ('3302'::character varying)::text, ('3049'::character varying)::text, ('3274'::character varying)::text])) AND (h.payment_start_dt = tb_main.payment_start_dt) AND (pd.draft_service_id IS NOT NULL)))))) AND (d.draft_service_id IS NOT NULL))) tb_main_1
                          GROUP BY tb_main_1.program_nm) tb1_group) tb1_com) AS comment
   FROM ( SELECT ( SELECT tb_contract_program.program_nm
                   FROM prov.tb_contract_program
                  WHERE (tb_contract_program.contract_id = ( SELECT DISTINCT tb_placement_delete.contract_program_id
                           FROM tb_placement_delete
                          WHERE (tb_placement_delete.placement_id = d.placement_id)))) AS program_nm,
            d.client_id,
            d.draft_amount_no,
            d.payment_id,
            h1.provider_id,
            h1.payment_start_dt
           FROM tb_payment_detail d,
            tb_payment_header h1
          WHERE ((d.payment_id = h1.payment_id) AND (d.payment_id IN ( SELECT ph.payment_id
                   FROM (tb_payment_header ph
                     JOIN prov.tb_provider p ON (((ph.provider_id = p.provider_id) AND (ph.delete_sw = 'N'::bpchar))))
                  WHERE (ph.payment_id IN ( SELECT DISTINCT h.payment_id
                           FROM (tb_payment_header h
                             JOIN tb_payment_detail pd ON ((h.payment_id = pd.payment_id)))
                          WHERE (((h.payment_type_cd)::text = '6'::text) AND (h.delete_sw = 'N'::bpchar) AND (pd.delete_sw = 'N'::bpchar) AND ((f_prvpcklst_cat(h.provider_id, 'PLACEMENT'::character varying))::text = ANY (ARRAY[('1782'::character varying)::text, ('3302'::character varying)::text, ('3049'::character varying)::text, ('3274'::character varying)::text])) AND (pd.draft_service_id IS NOT NULL)))))) AND (d.delete_sw = 'N'::bpchar) AND (d.draft_service_id IS NOT NULL))) tb_main
  GROUP BY tb_main.program_nm, tb_main.payment_id, tb_main.provider_id, tb_main.payment_start_dt
  ORDER BY tb_main.program_nm;


