--
-- TOC entry 7272 (class 1259 OID 158996229)
-- Name: fm120r_mps_private_detail_view; Type: VIEW; Schema: cjams; Owner: cjams_prod_admin
--

CREATE VIEW fm120r_mps_private_detail_view AS
 SELECT DISTINCT d.payment_id,
    pr.provider_nm,
    d.client_id AS child_id,
    ( SELECT tb_contract_program.program_nm
           FROM prov.tb_contract_program
          WHERE (tb_contract_program.contract_id IN ( SELECT DISTINCT tb_placement_delete.contract_program_id
                   FROM tb_placement_delete
                  WHERE (tb_placement_delete.placement_id = d.placement_id)))) AS program_nm,
        CASE
            WHEN (d.client_id > 0) THEN ( SELECT DISTINCT l.lastname
               FROM person l
              WHERE (l.cjamspid = d.client_id))
            ELSE ''::character varying
        END AS last_nm,
        CASE
            WHEN (d.client_id > 0) THEN ( SELECT DISTINCT l.firstname
               FROM person l
              WHERE (l.cjamspid = d.client_id))
            ELSE ''::character varying
        END AS first_nm,
    d.draft_service_start_dt AS start_date,
