   FROM tb_payment_header ph,
    tb_payment_detail pd
  WHERE ((ph.payment_id = pd.payment_id) AND ((ph.payment_type_cd)::text = '6'::text) AND (ph.delete_sw = 'N'::bpchar) AND (pd.delete_sw = 'N'::bpchar) AND (ph.payment_start_dt = p.payment_start_dt) AND ((f_prvpcklst_cat(ph.provider_id, 'PLACEMENT'::character varying))::text <> '1783'::text) AND ((pd.draft_amount_no <> pd.final_amount_no) OR ((pd.draft_amount_no IS NULL) AND (pd.final_amount_no IS NOT NULL)) OR ((pd.draft_amount_no IS NOT NULL) AND (pd.final_amount_no IS NULL)) OR (ph.offset_amount_no > (0)::numeric)))))) tb_main
                          GROUP BY tb_main.program_nm, tb_main.payment_id) tb1_group
