   FROM prov.tb_contract_program
  WHERE (tb_contract_program.contract_id IN ( SELECT DISTINCT tb_placement_delete.contract_program_id
     FROM tb_placement_delete
    WHERE (tb_placement_delete.placement_id = d.placement_id)))) AS program_nm
                                   FROM tb_payment_detail d
                                  WHERE ((d.delete_sw = 'N'::bpchar) AND (d.payment_id IN ( SELECT ph.payment_id
   FROM (tb_payment_header ph1
     JOIN tb_payment_detail pd ON ((ph1.payment_id = pd.payment_id)))
  WHERE (((ph1.payment_type_cd)::text = '6'::text) AND (ph1.delete_sw = 'N'::bpchar) AND (pd.delete_sw = 'N'::bpchar) AND ((f_prvpcklst_cat(ph1.provider_id, 'PLACEMENT'::character varying))::text = ANY (ARRAY[('1782'::character varying)::text, ('3302'::character varying)::text, ('3049'::character varying)::text, ('3274'::character varying)::text])) AND (ph1.payment_start_dt = ph.payment_start_dt) AND ((pd.draft_amount_no <> pd.final_amount_no) OR ((pd.draft_amount_no IS NULL) AND (pd.final_amount_no IS NOT NULL)) OR ((pd.draft_amount_no IS NOT NULL) AND (pd.final_amount_no IS NULL)) OR (ph1.offset_amount_no > (0)::numeric))))))) tb_main
                          GROUP BY tb_main.payment_id, tb_main.program_nm) tb1_group
                  GROUP BY tb1_group.payment_id) tb1_com
          WHERE (tb1_com.payment_id = ph.payment_id)) AS comment
   FROM (tb_payment_header ph
