                            WHEN (((sum(tab_1.num_pages) + 1) > 12) AND ((sum(tab_1.num_pages) + 1) <= 24)) THEN 'BI-FOLD'::text
                            ELSE 'NO-FOLD'::text
                        END AS comment
                   FROM ( SELECT d_1.county_cd,
                            count(d_1.client_id) AS child_count,
                            f_rpt_num_pages(count(d_1.client_id)) AS num_pages
                           FROM tb_payment_detail d_1
                          WHERE ((d_1.delete_sw = 'N'::bpchar) AND (d_1.payment_id IN ( SELECT ph.payment_id
                                   FROM (tb_payment_header ph
                                     JOIN prov.tb_provider p ON (((ph.provider_id = p.provider_id) AND (p.delete_sw = 'N'::bpchar))))
                                  WHERE (ph.payment_id IN ( SELECT h.payment_id
   FROM (tb_payment_header h
     JOIN tb_payment_detail pd ON ((h.payment_id = pd.payment_id)))
  WHERE (((h.payment_type_cd)::text = '6'::text) AND (h.delete_sw = 'N'::bpchar) AND (pd.delete_sw = 'N'::bpchar) AND ((f_prvpcklst_cat(h.provider_id, 'PLACEMENT'::character varying))::text = '1783'::text) AND (h.payment_start_dt = h1.payment_start_dt) AND ((pd.draft_amount_no <> pd.final_amount_no) OR ((pd.draft_amount_no IS NULL) AND (pd.final_amount_no IS NOT NULL)) OR ((pd.draft_amount_no IS NOT NULL) AND (pd.final_amount_no IS NULL)) OR (h.offset_amount_no > (0)::numeric))))))))
                          GROUP BY d_1.county_cd) tab_1) tab_com) AS comment,
    d.payment_id,
    h1.provider_id,
    h1.payment_start_dt
   FROM tb_payment_detail d,
    tb_payment_header h1
  WHERE ((d.delete_sw = 'N'::bpchar) AND (h1.payment_id = d.payment_id) AND (d.payment_id IN ( SELECT ph.payment_id
           FROM (tb_payment_header ph
             JOIN prov.tb_provider p ON (((ph.provider_id = p.provider_id) AND (p.delete_sw = 'N'::bpchar))))
          WHERE (ph.payment_id IN ( SELECT h.payment_id
                   FROM (tb_payment_header h
                     JOIN tb_payment_detail pd ON ((h.payment_id = pd.payment_id)))
                  WHERE (((h.payment_type_cd)::text = '6'::text) AND (h.delete_sw = 'N'::bpchar) AND (pd.delete_sw = 'N'::bpchar) AND ((f_prvpcklst_cat(h.provider_id, 'PLACEMENT'::character varying))::text = '1783'::text) AND ((pd.draft_amount_no <> pd.final_amount_no) OR ((pd.draft_amount_no IS NULL) AND (pd.final_amount_no IS NOT NULL)) OR ((pd.draft_amount_no IS NOT NULL) AND (pd.final_amount_no IS NULL)) OR (h.offset_amount_no > (0)::numeric))))))))
  GROUP BY d.county_cd, d.payment_id, h1.provider_id, h1.payment_start_dt;


