    ( SELECT tb1_com.comment
           FROM ( SELECT (sum(tab_1.num_pages) + 1) AS num_pages,
                        CASE
                            WHEN ((sum(tab_1.num_pages) + 1) <= 12) THEN 'TRI-FOLD'::text
                            WHEN (((sum(tab_1.num_pages) + 1) > 12) AND ((sum(tab_1.num_pages) + 1) <= 24)) THEN 'BI-FOLD'::text
                            ELSE 'NO-FOLD'::text
                        END AS comment
                   FROM ( SELECT d_1.county_cd,
                            count(d_1.client_id) AS child_count,
                            f_rpt_num_pages(count(d_1.client_id)) AS num_pages
                           FROM tb_payment_detail d_1
                          WHERE ((d_1.delete_sw = 'N'::bpchar) AND (d_1.payment_id IN ( SELECT ph.payment_id
                                   FROM (tb_payment_header ph
                                     JOIN prov.tb_provider p ON (((ph.provider_id = p.provider_id) AND (p.delete_sw = 'N'::bpchar))))
                                  WHERE (ph.payment_id IN ( SELECT h1.payment_id
   FROM (tb_payment_header h1
     JOIN tb_payment_detail pd ON ((h1.payment_id = pd.payment_id)))
  WHERE (((h1.payment_type_cd)::text = '6'::text) AND (h1.delete_sw = 'N'::bpchar) AND (pd.delete_sw = 'N'::bpchar) AND ((f_prvpcklst_cat(h.provider_id, 'PLACEMENT'::character varying))::text = '1783'::text) AND (h1.payment_start_dt = h.payment_start_dt) AND ((pd.draft_amount_no <> pd.final_amount_no) OR ((pd.draft_amount_no IS NULL) AND (pd.final_amount_no IS NOT NULL)) OR ((pd.draft_amount_no IS NOT NULL) AND (pd.final_amount_no IS NULL)) OR (h1.offset_amount_no > (0)::numeric))))))))
                          GROUP BY d_1.county_cd) tab_1) tb1_com) AS comment,
    h.payment_start_dt
   FROM tb_payment_header h,
    tb_payment_detail d,
    prov.tb_provider pr
  WHERE ((h.provider_id = pr.provider_id) AND (h.payment_id = d.payment_id) AND (d.delete_sw = 'N'::bpchar) AND (h.delete_sw = 'N'::bpchar) AND (pr.delete_sw = 'N'::bpchar) AND (d.payment_id IN ( SELECT ph.payment_id
