    COALESCE(ph.offset_amount_no, (0)::numeric) AS offset_amount_no,
    COALESCE((( SELECT sum(COALESCE(tb_payment_detail.final_amount_no, (0)::numeric)) AS sum
           FROM tb_payment_detail
          WHERE ((tb_payment_detail.payment_id = ph.payment_id) AND (tb_payment_detail.delete_sw = 'N'::bpchar))) - COALESCE(ph.offset_amount_no, (0)::numeric)), (0)::numeric) AS net_amount_no,
    ph.payment_start_dt,
