                        CASE
                            WHEN ((sum(tab_1.num_pages) + 1) <= 12) THEN 'TRI-FOLD'::text
                            WHEN (((sum(tab_1.num_pages) + 1) > 12) AND ((sum(tab_1.num_pages) + 1) <= 24)) THEN 'BI-FOLD'::text
                            ELSE 'NO-FOLD'::text
                        END AS comment,
                    tab_1.payment_id
                   FROM ( SELECT d.county_cd,
                            count(d.client_id) AS child_count,
                            f_rpt_num_pages(count(d.client_id)) AS num_pages,
                            d.payment_id
                           FROM tb_payment_detail d
                          WHERE ((d.delete_sw = 'N'::bpchar) AND (d.payment_id IN ( SELECT ph_1.payment_id
                                   FROM (tb_payment_header ph_1
                                     JOIN prov.tb_provider p_1 ON (((ph_1.provider_id = p_1.provider_id) AND (p_1.delete_sw = 'N'::bpchar))))
                                  WHERE (ph_1.payment_id IN ( SELECT h.payment_id
   FROM (tb_payment_header h
     JOIN tb_payment_detail pd ON ((h.payment_id = pd.payment_id)))
  WHERE (((h.payment_type_cd)::text = '6'::text) AND (h.delete_sw = 'N'::bpchar) AND (pd.delete_sw = 'N'::bpchar) AND ((f_prvpcklst_cat(h.provider_id, 'PLACEMENT'::character varying))::text = '1783'::text) AND (h.payment_start_dt = ph_1.payment_start_dt) AND ((pd.draft_amount_no <> pd.final_amount_no) OR ((pd.draft_amount_no IS NULL) AND (pd.final_amount_no IS NOT NULL)) OR ((pd.draft_amount_no IS NOT NULL) AND (pd.final_amount_no IS NULL)) OR (h.offset_amount_no > (0)::numeric)))))
                                  GROUP BY ph_1.payment_id)))
                          GROUP BY d.county_cd, d.payment_id) tab_1
                  GROUP BY tab_1.payment_id) tb1_com
          WHERE (tb1_com.payment_id = ph.payment_id)) AS comment
   FROM (tb_payment_header ph
     JOIN prov.tb_provider p ON (((ph.provider_id = p.provider_id) AND (p.delete_sw = 'N'::bpchar))))
  WHERE (ph.payment_id IN ( SELECT h.payment_id
           FROM (tb_payment_header h
