CREATE VIEW fm210r_private_view AS
 SELECT DISTINCT tb_fm210r.provider_id,
        CASE
            WHEN (tb_fm210r.provider_nm IS NULL) THEN (tb_fm210r.first_last_nm)::character varying
            ELSE tb_fm210r.provider_nm
        END AS provider_nm,
    tb_fm210r.provider_address,
    f_pdesc(tb_fm210r.provider_county, 104) AS provider_county_nm,
    ( SELECT (((userprofile.lastname)::text || ' '::text) || (userprofile.firstname)::text)
           FROM userprofile
          WHERE (userprofile.cjamspid = tb_fm210r.assign_to_staff_id)) AS caseworker_nm,
    tb_fm210r.client_nm,
    tb_fm210r.child_id,
    tb_fm210r.dob,
    tb_fm210r.placement_structure_service,
    tb_fm210r.from_dt AS start_dt,
    tb_fm210r.to_dt AS end_dt,
    tb_fm210r.payment_id,
    tb_fm210r.amount AS overpayment_amount,
    tb_fm210r.ldss AS child_ldss,
    tb_fm210r.program_nm,
    tb_fm210r.create_ts
   FROM ( SELECT rh.provider_id,
            ((((COALESCE(pr.provider_first_nm, ''::character varying))::text || ' '::text) || COALESCE(((pr.provider_middle_nm)::text || ' '::text), ''::text)) || (COALESCE(pr.provider_last_nm, ''::character varying))::text) AS first_last_nm,
                CASE
                    WHEN ((pr.provider_nm)::text = ' '::text) THEN NULL::character varying
                    ELSE pr.provider_nm
                END AS provider_nm,
            f_provider_add('TB_PROVIDER_ADDRESSES'::character varying, rh.provider_id, '3356'::character varying) AS provider_address,
            ((((COALESCE(c.lastname, ''::character varying))::text || ' '::text) || (COALESCE(c.firstname, ''::character varying))::text) || COALESCE((','::text || (
                CASE
                    WHEN ((c.middlename)::text = ' '::text) THEN NULL::character varying
                    ELSE c.middlename
                END)::text), ''::text)) AS client_nm,
            c.dob,
            (((f_servicename(pd.final_service_id))::text || ' '::text) || COALESCE(('-'::text || (f_plvalue(pd.final_rate_type_cd, 82))::text), ''::text)) AS placement_structure_service,
            pd.final_service_start_dt AS from_dt,
            pd.final_service_end_dt AS to_dt,
            rd.amount_no AS amount,
            f_plvalue(rd.county_cd, 104) AS ldss,
            pd.client_id AS child_id,
            pr.county_cd AS provider_county,
            ( SELECT DISTINCT tb_provider_picklist.picklist_value_cd
                   FROM prov.tb_provider_picklist
                  WHERE (((tb_provider_picklist.picklist_value_cd)::text = ANY (ARRAY[('1782'::character varying)::text, ('1783'::character varying)::text, ('1785'::character varying)::text, ('3049'::character varying)::text, ('3274'::character varying)::text, ('3302'::character varying)::text])) AND (tb_provider_picklist.provider_id = rh.provider_id) AND (tb_provider_picklist.delete_sw = 'N'::bpchar))) AS provider_cat,
            ( SELECT DISTINCT tb_assignment.assign_to_staff_id
                   FROM tb_assignment
                  WHERE (tb_assignment.assignment_id IN ( SELECT max(tb_assignment_1.assignment_id) AS max
                           FROM tb_assignment tb_assignment_1
                          WHERE ((tb_assignment_1.delete_sw = 'N'::bpchar) AND (tb_assignment_1.start_dt <= now()) AND ((tb_assignment_1.end_dt IS NULL) OR (tb_assignment_1.end_dt > now())) AND ((tb_assignment_1.responsibility_cd)::text = 'P'::text) AND (tb_assignment_1.entity_key_id = pd.case_id))
                          GROUP BY tb_assignment_1.entity_key_id))) AS assign_to_staff_id,
            pd.payment_id,
            ( SELECT DISTINCT tb_contract_program.program_nm
                   FROM prov.tb_contract_program
                  WHERE (tb_contract_program.program_id IN ( SELECT tb_placement_delete.contract_program_id
                           FROM tb_placement_delete
                          WHERE (tb_placement_delete.placement_id = pd.placement_id)))) AS program_nm,
            (rd.create_ts)::date AS create_ts
           FROM tb_receivable_header rh,
            person c,
            tb_payment_detail pd,
            tb_receivable_detail rd,
            prov.tb_provider pr
          WHERE (((c.cjamspid)::text = ((pd.client_id)::character varying)::text) AND ((( SELECT DISTINCT tb_provider_picklist.picklist_value_cd
                   FROM prov.tb_provider_picklist
                  WHERE (((tb_provider_picklist.picklist_value_cd)::text = ANY (ARRAY[('1782'::character varying)::text, ('1783'::character varying)::text, ('1785'::character varying)::text, ('3049'::character varying)::text, ('3274'::character varying)::text, ('3302'::character varying)::text])) AND (tb_provider_picklist.provider_id = rh.provider_id) AND (tb_provider_picklist.delete_sw = 'N'::bpchar))))::text = ANY (ARRAY[('1782'::character varying)::text, ('3302'::character varying)::text, ('3049'::character varying)::text, ('3274'::character varying)::text])) AND (rh.receivable_id = rd.receivable_id) AND (rd.payment_detail_id = pd.payment_detail_id) AND (pr.provider_id = rh.provider_id) AND ((("substring"((rd.create_ts)::text, 1, 2) = (13)::text) AND ((rd.receivable_status_cd)::text = ANY (ARRAY[('19'::character varying)::text, ('20'::character varying)::text])) AND (rd.receivable_balance_no >= (0)::numeric)) OR (("substring"((rd.create_ts)::text, 1, 2) <> (13)::text) AND ((rd.receivable_status_cd)::text = '19'::text) AND (rd.receivable_balance_no > (0)::numeric))) AND ((rd.manual_sw = 'N'::bpchar) OR ((rd.manual_sw = 'Y'::bpchar) AND ((rd.approval_status_cd)::text = '3047'::text))) AND (c.activeflag = 1) AND (rh.delete_sw = 'N'::bpchar) AND (pd.delete_sw = 'N'::bpchar) AND (pr.delete_sw = 'N'::bpchar) AND (rd.delete_sw = 'N'::bpchar) AND ((rh.provider_id IN ( SELECT DISTINCT tb_placement_delete.provider_id
                   FROM tb_placement_delete
                  WHERE ((tb_placement_delete.entry_dt IS NOT NULL) AND ((tb_placement_delete.exit_dt IS NULL) OR (tb_placement_delete.exit_dt > date(((rd.create_ts)::date - '1 day'::interval)))) AND ((tb_placement_delete.void_sw IS NULL) OR (tb_placement_delete.void_sw = 'N'::bpchar) OR (rtrim(ltrim((tb_placement_delete.void_sw)::text)) = ''::text)) AND (tb_placement_delete.delete_sw = 'N'::bpchar)))) OR (rh.provider_id IN ( SELECT DISTINCT tb_placement_delete.provider_organization_id
                   FROM tb_placement_delete
                  WHERE ((tb_placement_delete.entry_dt IS NOT NULL) AND ((tb_placement_delete.exit_dt IS NULL) OR (tb_placement_delete.exit_dt > date(((rd.create_ts)::date - '1 day'::interval)))) AND ((tb_placement_delete.void_sw IS NULL) OR (tb_placement_delete.void_sw = 'N'::bpchar) OR (rtrim(ltrim((tb_placement_delete.void_sw)::text)) = ''::text)) AND (tb_placement_delete.delete_sw = 'N'::bpchar))))))) tb_fm210r
  ORDER BY tb_fm210r.provider_id, tb_fm210r.program_nm, ( SELECT (((userprofile.lastname)::text || ' '::text) || (userprofile.firstname)::text)
           FROM userprofile
          WHERE (userprofile.cjamspid = tb_fm210r.assign_to_staff_id)), tb_fm210r.child_id, tb_fm210r.client_nm, tb_fm210r.placement_structure_service, tb_fm210r.from_dt, tb_fm210r.to_dt, tb_fm210r.payment_id, tb_fm210r.amount, tb_fm210r.ldss;


