--
-- TOC entry 7683 (class 1259 OID 158999290)
-- Name: mv_getworkloadassignmentsummary; Type: MATERIALIZED VIEW; Schema: cjams; Owner: cjams_prod_admin
--

CREATE MATERIALIZED VIEW mv_getworkloadassignmentsummary AS
 SELECT sum(1) AS totalcnt,
    sum(
        CASE
            WHEN ((ca.enddate IS NULL) AND (COALESCE(tma.issupervisor, 0) = 0)) THEN 1
            ELSE 0
        END) AS opencnt,
    sum(
        CASE
            WHEN ((ca.enddate IS NOT NULL) AND (COALESCE(tma.issupervisor, 0) = 0)) THEN 1
            ELSE 0
        END) AS closedcnt,
    sum(
        CASE
            WHEN (ca.enddate IS NULL) THEN 1
            ELSE 0
        END) AS vsumopencnt,
    sum(
        CASE
            WHEN (ca.enddate IS NOT NULL) THEN 1
            ELSE 0
        END) AS vsumclosedcnt,
    sum(
        CASE COALESCE(tma.issupervisor, 0)
            WHEN 1 THEN 1
            ELSE 0
        END) AS ytscnt,
    pt.teamid,
    pt.teamname
   FROM (((( SELECT ca_1.startdate,
            ca_1.enddate,
            NULL::timestamp without time zone AS insertedon,
            ca_1.toteamid,
            ca_1.toworkeridno,
            ca_1.activeflag
           FROM caseassignment ca_1
        UNION ALL
         SELECT NULL::timestamp without time zone AS startdate,
            NULL::timestamp without time zone AS enddate,
            r.insertedon,
            r.teamid AS toteamid,
            r.tosecurityusersid AS toworkeridno,
            r.activeflag
           FROM routing r
          WHERE ((r.routingstatustypeid = 1) AND ((r.eventcode)::text = 'INTR'::text))) ca
     JOIN team t ON (((t.teamid = ca.toteamid) AND (t.activeflag = 1))))
     JOIN team pt ON (((pt.teamid = t.parentteamid) AND ((pt.teamtypekey)::text = 'LDSS'::text) AND (pt.activeflag = 1))))
     LEFT JOIN ( SELECT tma_1.securityusersid,
            1 AS issupervisor
           FROM ((teammemberassignment tma_1
             JOIN teammember tm ON (((tm.teammemberid = tma_1.teammemberid) AND (tm.activeflag = 1))))
             JOIN teammemberroletype tmrt ON ((((tmrt.roletypekey)::text = (tm.roletypekey)::text) AND (tmrt.activeflag = 1) AND (tmrt.isupervisor = true) AND (tma_1.activeflag = 1))))) tma ON (((tma.securityusersid)::text = (ca.toworkeridno)::text)))
  WHERE (ca.activeflag = 1)
  GROUP BY pt.teamid, pt.teamname
  WITH NO DATA;


ALTER TABLE mv_getworkloadassignmentsummary OWNER TO cjams_prod_admin;

