--
-- TOC entry 8471 (class 1259 OID 159004504)
-- Name: tb_adoption; Type: VIEW; Schema: cjams; Owner: cjams_prod_admin
--

CREATE VIEW tb_adoption AS
 SELECT a.alternateid AS adoption_id,
    NULL::text AS ma_only_payment_cd,
    (a.adoptioncasenumber)::bigint AS case_id,
    a.adoptioncaseid AS adoption_case_id,
    a.startdate AS subsidy_start_dt,
    a.enddate AS subsidy_end_dt,
    p.cjamspid AS client_id,
    'N'::character varying AS delete_sw,
    a.insertedby AS create_user_id,
    a.insertedon AS create_ts,
    a.updatedby AS update_user_id,
    a.updatedon AS update_ts
   FROM ((adoptioncase a
     JOIN adoptioncaseactor aca ON (((aca.adoptioncaseid = a.adoptioncaseid) AND ((aca.actortypekey)::text = 'CHILD'::text) AND (aca.activeflag = 1))))
     JOIN person p ON (((p.personid = aca.personid) AND (p.activeflag = 1))))
  WHERE (a.activeflag = 1);


ALTER TABLE tb_adoption OWNER TO cjams_prod_admin;

