--
-- TOC entry 8827 (class 1259 OID 159006533)
-- Name: v_provider; Type: VIEW; Schema: cjams; Owner: cjams_prod_admin
--

CREATE VIEW v_provider AS
 SELECT DISTINCT tb_payment_header.provider_id
   FROM tb_payment_header,
    tb_payment_detail,
    tb_payment_status,
    prov.tb_provider
  WHERE ((tb_payment_header.payment_id = tb_payment_detail.payment_id) AND (tb_payment_header.payment_id = tb_payment_status.payment_id) AND ((tb_payment_status.payment_status_cd)::text = '1636'::text) AND ((tb_payment_detail.delete_sw)::text = 'N'::text) AND ((tb_payment_header.payment_type_cd)::text = '3294'::text) AND (tb_payment_header.delete_sw = 'N'::bpchar) AND (tb_payment_status.delete_sw = 'N'::bpchar) AND (tb_payment_header.provider_id = tb_provider.provider_id) AND (tb_payment_header.manual_sw = 'N'::bpchar) AND ((( SELECT DISTINCT tb_provider_picklist.picklist_value_cd
           FROM prov.tb_provider_picklist
          WHERE (((tb_provider_picklist.picklist_value_cd)::text = ANY (ARRAY[('1782'::character varying)::text, ('1783'::character varying)::text, ('3049'::character varying)::text, ('3274'::character varying)::text, ('3302'::character varying)::text])) AND (tb_provider_picklist.provider_id = tb_provider.provider_id) AND (tb_provider_picklist.delete_sw = 'N'::bpchar))))::text = ANY (ARRAY[('1782'::character varying)::text, ('3302'::character varying)::text, ('3049'::character varying)::text, ('3274'::character varying)::text, ('1783'::character varying)::text])) AND (NOT (COALESCE(tb_payment_detail.linked_pymnt_hdr_id, 0) IN ( SELECT tb_payment_header_1.payment_id
           FROM (tb_payment_status tb_payment_status_1
             JOIN tb_payment_header tb_payment_header_1 ON ((tb_payment_status_1.payment_id = tb_payment_header_1.payment_id)))
          WHERE (((tb_payment_status_1.payment_status_cd)::text = '1639'::text) AND (tb_payment_header_1.delete_sw = 'N'::bpchar) AND (tb_payment_status_1.delete_sw = 'N'::bpchar) AND ((tb_payment_header_1.payment_type_cd)::text <> '6'::text))))))
 LIMIT 100;


ALTER TABLE v_provider OWNER TO cjams_prod_admin;

