--
-- TOC entry 8829 (class 1259 OID 159006546)
-- Name: v_provider_addresses; Type: VIEW; Schema: cjams; Owner: cjams_prod_admin
--

CREATE VIEW v_provider_addresses AS
 SELECT DISTINCT a.address_id,
    a.parent_key_id,
    a.adr_type_cd,
    a.adr_format_cd,
    a.adr_street_no,
    a.adr_box_no,
    a.adr_pre_dir_cd,
    a.adr_street_nm,
    a.adr_street_suffix_cd,
    a.adr_post_dir_cd,
    a.adr_unit_type_cd,
    a.adr_unit_no_tx,
    a.adr_city_nm,
    a.adr_county_cd,
    a.adr_state_cd,
    a.adr_zip5_no,
    a.adr_zip4_no,
    a.adr_direction_tx,
    a.adr_foreign_tx,
    a.adr_foreign_state_tx,
    a.adr_country_tx,
    a.adr_postal_code_tx,
    a.adr_default_sw,
    a.adr_start_dt,
    a.adr_end_dt,
    a.create_ts,
    a.create_user_id,
    a.update_ts,
    a.update_user_id,
    a.delete_sw,
    a.adr_street_tx,
    b.provider_id AS parent_key_id1
   FROM prov.tb_provider_addresses a,
    ( SELECT v_provider.provider_id
           FROM v_provider) b
  WHERE (((a.adr_type_cd)::text = (3356)::text) AND (a.delete_sw = 'N'::bpchar))
  ORDER BY a.address_id DESC;


ALTER TABLE v_provider_addresses OWNER TO cjams_prod_admin;

