--
-- TOC entry 8834 (class 1259 OID 159006572)
-- Name: v_userprofile; Type: VIEW; Schema: cjams; Owner: cjams_prod_admin
--

CREATE VIEW v_userprofile AS
 SELECT m.id AS userid,
    m.securityusersid,
    m.email,
    m.username,
    up.firstname,
    up.lastname,
    up.displayname,
    up.fullname,
    up.teamtypekey AS userteamtype,
        CASE
            WHEN ((up.supervisorid IS NULL) OR ((up.supervisorid)::text = '00000000-0000-0000-0000-000000000000'::text)) THEN tm.supervisorid
            ELSE up.supervisorid
        END AS supervisorid,
    up.cjamspid,
    (
        CASE COALESCE(up.unavailableflag, false)
            WHEN true THEN 'No'::text
            ELSE 'Yes'::text
        END)::character varying AS useravailable,
    tm.roletypekey,
    tm.loadnumber,
    tm.teammemberid,
    tmrt.description,
    tmrt.isupervisor,
    tmrt.teamtypekey AS agency,
    t.teamid,
    t.teamname,
    t.teamnumber,
    t.teamtypekey AS teamkey,
    t.parentteamid,
    t.description AS teamdescription,
    (t.countyid)::uuid AS countyid,
    ( SELECT county.statecountycode
           FROM county
          WHERE ((county.activeflag = 1) AND (county.countyid = (t.countyid)::uuid))
         LIMIT 1) AS statecountycode,
    ( SELECT county.countyname
           FROM county
          WHERE ((county.activeflag = 1) AND (county.countyid = (t.countyid)::uuid))
         LIMIT 1) AS countyname
   FROM (((((muser m
     JOIN userprofile up ON ((((m.securityusersid)::text = (up.securityusersid)::text) AND (m.activeflag = 1) AND (up.activeflag = 1))))
     JOIN teammemberassignment tma ON ((((tma.securityusersid)::text = (up.securityusersid)::text) AND (tma.activeflag = 1))))
     JOIN teammember tm ON (((tm.teammemberid = tma.teammemberid) AND (tm.activeflag = 1))))
     JOIN teammemberroletype tmrt ON ((((tmrt.roletypekey)::text = (tm.roletypekey)::text) AND (tmrt.activeflag = 1))))
     JOIN team t ON (((t.teamid = tm.teamid) AND (tm.activeflag = 1))))
  WHERE ((up.expirationdate IS NULL) OR (up.expirationdate > now()));


ALTER TABLE v_userprofile OWNER TO cjams_prod_admin;

