--
-- TOC entry 6462 (class 1259 OID 15185)
-- Name: sysobjects; Type: VIEW; Schema: dbo; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW dbo.sysobjects AS
 SELECT su.uid,
    ((lower(ao.schema_name) || '.'::text) || lower(ao.object_name)) AS name,
    'U'::text AS xtype
   FROM all_objects ao,
    sysusers su
  WHERE ((lower(ao.owner) = su.name) AND (ao.object_type = 'TABLE'::text))
UNION
 SELECT su.uid,
    ((lower(ao.schema_name) || '.'::text) || lower(ao.object_name)) AS name,
    'I'::text AS xtype
   FROM all_objects ao,
    sysusers su
  WHERE ((lower(ao.owner) = su.name) AND (ao.object_type = 'INDEX'::text))
UNION
 SELECT su.uid,
    ((lower(ao.schema_name) || '.'::text) || lower(ao.object_name)) AS name,
    'S'::text AS xtype
   FROM all_objects ao,
    sysusers su
  WHERE ((lower(ao.owner) = su.name) AND (ao.object_type = 'SEQUENCE'::text))
UNION
 SELECT su.uid,
    ((lower(ao.schema_name) || '.'::text) || lower(ao.object_name)) AS name,
    'V'::text AS xtype
   FROM all_objects ao,
    sysusers su
  WHERE ((lower(ao.owner) = su.name) AND (ao.object_type = 'VIEW'::text))
UNION
 SELECT su.uid,
    ((lower(ao.schema_name) || '.'::text) || lower(ao.object_name)) AS name,
    'P'::text AS xtype
   FROM all_objects ao,
    sysusers su
  WHERE ((lower(ao.owner) = su.name) AND (ao.object_type = ANY (ARRAY['PROCEDURE'::text, 'FUNCTION'::text, 'PACKAGE'::text])))
UNION
 SELECT su.uid,
    ((lower(ao.schema_name) || '.'::text) || lower(ao.object_name)) AS name,
    'TR'::text AS xtype
   FROM all_objects ao,
    sysusers su
  WHERE ((lower(ao.owner) = su.name) AND (ao.object_type = 'TRIGGER'::text))
UNION
 SELECT su.uid,
    ((lower(ao.schema_name) || '.'::text) || lower(ao.object_name)) AS name,
    'M'::text AS xtype
   FROM all_objects ao,
    sysusers su
  WHERE ((lower(ao.owner) = su.name) AND (ao.object_type = 'SYNONYM'::text));


ALTER TABLE dbo.sysobjects OWNER TO "mdt-mdm-edb-cjm-prd";

