--
-- TOC entry 8897 (class 1259 OID 159006961)
-- Name: job_execution_log; Type: VIEW; Schema: etl_data_val; Owner: cjams_prod_admin
--

CREATE VIEW etl_data_val.job_execution_log AS
 SELECT DISTINCT t1.pid AS job_id,
    t1.job_name,
    min(t1.job_start_datetime) AS start_datetime,
    max(t2.job_end_datetime) AS end_datetime,
    t2.job_execution_status,
    t1.data_environment
   FROM (( SELECT DISTINCT talend_stats_table.moment AS job_start_datetime,
            talend_stats_table.pid,
            talend_stats_table.job AS job_name,
            talend_stats_table.job_repository_id AS job_id,
            talend_stats_table.context AS data_environment
           FROM etl_data_val.talend_stats_table
          WHERE ((talend_stats_table.message_type)::text = 'begin'::text)) t1
     JOIN ( SELECT DISTINCT talend_stats_table.moment AS job_end_datetime,
            talend_stats_table.pid,
            talend_stats_table.job AS job_name,
            talend_stats_table.job_repository_id AS job_id,
            talend_stats_table.message_type,
            talend_stats_table.message AS job_execution_status
           FROM etl_data_val.talend_stats_table
          WHERE ((talend_stats_table.message_type)::text = 'end'::text)) t2 ON (((t1.pid)::text = (t2.pid)::text)))
  GROUP BY t1.pid, t1.job_name, t2.job_execution_status, t1.data_environment;


ALTER TABLE etl_data_val.job_execution_log OWNER TO cjams_prod_admin;

