ALTER TABLE etl_data_val.talend_meter_table OWNER TO cjams_prod_admin;

--
-- TOC entry 8917 (class 1259 OID 159007077)
-- Name: table_status_log; Type: VIEW; Schema: etl_data_val; Owner: cjams_prod_admin
--

CREATE VIEW etl_data_val.table_status_log AS
 SELECT DISTINCT s1.pid,
    src.nm AS source_table_name,
    tgt.nm AS target_table_name,
    src_count.vl AS source_count,
    tgt_count.vl AS target_count,
    max(s1.moment) AS loaded_date
   FROM etl_data_val.talend_meter_table s1,
    ( SELECT DISTINCT s1_1.pid,
            substr((s1_1.label)::text, (0)::numeric, ("position"((s1_1.label)::text, '_'::text))::numeric) AS t_n,
            s1_1.label AS nm,
            substr((s1_1.label)::text, (10)::numeric) AS t_name
           FROM etl_data_val.talend_meter_table s1_1
          WHERE ((s1_1.label)::text ~~ '%Src%'::text)) src,
    ( SELECT DISTINCT s1_1.pid,
            substr((s1_1.label)::text, (0)::numeric, ("position"((s1_1.label)::text, '_'::text))::numeric) AS t_n,
            s1_1.label AS nm,
            substr((s1_1.label)::text, (10)::numeric) AS t_name
           FROM etl_data_val.talend_meter_table s1_1
          WHERE ((s1_1.label)::text ~~ '%Tgt%'::text)) tgt,
    ( SELECT DISTINCT s1_1.pid,
            substr((s1_1.label)::text, (0)::numeric, ("position"((s1_1.label)::text, '_'::text))::numeric) AS t_n,
            s1_1.count AS vl,
            substr((s1_1.label)::text, (10)::numeric) AS t_name
           FROM etl_data_val.talend_meter_table s1_1
          WHERE ((s1_1.label)::text ~~ '%Src%'::text)) src_count,
    ( SELECT DISTINCT s1_1.pid,
            substr((s1_1.label)::text, (0)::numeric, ("position"((s1_1.label)::text, '_'::text))::numeric) AS t_n,
            s1_1.count AS vl,
            substr((s1_1.label)::text, (10)::numeric) AS t_name
           FROM etl_data_val.talend_meter_table s1_1
          WHERE ((s1_1.label)::text ~~ '%Tgt%'::text)) tgt_count
  WHERE ((substr((s1.label)::text, (0)::numeric, ("position"((s1.label)::text, '_'::text))::numeric) = src.t_n) AND (substr((s1.label)::text, (0)::numeric, ("position"((s1.label)::text, '_'::text))::numeric) = tgt.t_n) AND (substr((s1.label)::text, (0)::numeric, ("position"((s1.label)::text, '_'::text))::numeric) = src_count.t_n) AND (substr((s1.label)::text, (0)::numeric, ("position"((s1.label)::text, '_'::text))::numeric) = tgt_count.t_n) AND ((s1.pid)::text = (src.pid)::text) AND ((s1.pid)::text = (tgt.pid)::text) AND ((s1.pid)::text = (src_count.pid)::text) AND ((s1.pid)::text = (tgt_count.pid)::text) AND (src_count.t_name = src.t_name) AND (tgt_count.t_name = tgt.t_name))
  GROUP BY s1.pid, src.nm, tgt.nm, src_count.vl, tgt_count.vl, (substr((s1.label)::text, (0)::numeric, ("position"((s1.label)::text, '_'::text))::numeric));


ALTER TABLE etl_data_val.table_status_log OWNER TO cjams_prod_admin;

