--
-- TOC entry 6391 (class 1259 OID 14853)
-- Name: all_all_tables; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.all_all_tables AS
 SELECT quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS owner,
    quote_ident_redwood((n.nspname)::text) AS schema_name,
    quote_ident_redwood((c.relname)::text) AS table_name,
    quote_ident_redwood((t.spcname)::text) AS tablespace_name,
    'VALID'::character varying(5) AS status,
        CASE
            WHEN (n.nspname ~~ 'pg_temp_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM ((pg_class c
     LEFT JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
     LEFT JOIN pg_tablespace t ON ((t.oid = c.reltablespace)))
  WHERE ((c.relkind = ANY (ARRAY['r'::"char", 'p'::"char"])) AND has_table_privilege(c.oid, 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER'::text) AND has_schema_privilege(n.oid, 'USAGE'::text) AND (n.nspname <> ALL (ARRAY['pg_catalog'::name, 'information_schema'::name, 'pg_toast'::name])));


ALTER TABLE sys.all_all_tables OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6409 (class 1259 OID 14937)
-- Name: all_cons_columns; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.all_cons_columns AS
 SELECT quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS owner,
    quote_ident_redwood((pn.nspname)::text) AS schema_name,
    quote_ident_redwood((pc.conname)::text) AS constraint_name,
    quote_ident_redwood((c.relname)::text) AS table_name,
    quote_ident_redwood((pa.attname)::text) AS column_name,
    ("position"."position")::smallint AS "position",
    quote_ident_redwood(pg_get_constraintdef(pc.oid)) AS constraint_def
   FROM (((((pg_attribute pa
     JOIN pg_constraint pc ON (((pc.conrelid = pa.attrelid) AND (pc.contype = ANY (ARRAY['f'::"char", 'u'::"char", 'p'::"char", 'c'::"char"])))))
     JOIN pg_namespace pn ON ((pn.oid = pc.connamespace)))
     LEFT JOIN pg_class c ON ((c.oid = pc.conrelid)))
     LEFT JOIN pg_index ind ON ((ind.indexrelid = pc.conindid)))
     LEFT JOIN LATERAL generate_series(1,
        CASE
            WHEN (pc.contype = ANY (ARRAY['f'::"char", 'p'::"char", 'u'::"char"])) THEN array_upper(pc.conkey, 1)
            ELSE 0
        END) "position"("position") ON (true))
  WHERE (has_column_privilege(c.oid, pa.attnum, 'SELECT, INSERT, UPDATE, REFERENCES'::text) AND has_schema_privilege(pn.oid, 'USAGE'::text) AND (pn.nspname <> ALL (ARRAY['pg_catalog'::name, 'information_schema'::name, 'pg_toast'::name])) AND (((pc.contype = 'f'::"char") AND (pa.attnum = pc.conkey[( SELECT key_i.key_i
           FROM generate_subscripts(pc.confkey, 1) key_i(key_i)
          WHERE (pc.confkey[key_i.key_i] = ind.indkey[("position"."position" - 1)]))])) OR ((pc.contype = ANY (ARRAY['u'::"char", 'p'::"char"])) AND (pa.attnum = pc.conkey["position"."position"])) OR ((pc.contype = 'c'::"char") AND (pa.attnum = ANY (pc.conkey)))));


ALTER TABLE sys.all_cons_columns OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6388 (class 1259 OID 14839)
-- Name: all_constraints; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.all_constraints AS
 SELECT quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS owner,
    quote_ident_redwood((pn.nspname)::text) AS schema_name,
    quote_ident_redwood((pc.conname)::text) AS constraint_name,
    quote_ident_redwood((pc.contype)::text) AS constraint_type,
    quote_ident_redwood((c.relname)::text) AS table_name,
    quote_ident_redwood(pc.consrc) AS search_condition,
        CASE
            WHEN (pc.contype = 'f'::"char") THEN quote_ident_redwood((pn2.nspname)::text)
            ELSE NULL::text
        END AS r_owner,
        CASE
            WHEN (pc.contype = 'f'::"char") THEN quote_ident_redwood((pc2.conname)::text)
            ELSE NULL::text
        END AS r_constraint_name,
    quote_ident_redwood((pc.confdeltype)::text) AS delete_rule,
    pc.condeferrable AS "deferrable",
    pc.condeferred AS deferred,
    quote_ident_redwood((ni.nspname)::text) AS index_owner,
    quote_ident_redwood((i.relname)::text) AS index_name,
    pg_get_constraintdef(pc.oid) AS constraint_def
   FROM (((((((pg_constraint pc
     LEFT JOIN pg_namespace pn ON ((pn.oid = pc.connamespace)))
     LEFT JOIN pg_class c ON ((c.oid = pc.conrelid)))
     LEFT JOIN pg_class i ON ((i.oid = pc.conindid)))
     LEFT JOIN pg_namespace ni ON ((i.relnamespace = ni.oid)))
     LEFT JOIN pg_class a ON ((a.oid = pc.confrelid)))
     LEFT JOIN pg_constraint pc2 ON (((pc.contype = 'f'::"char") AND (pc.confrelid = pc2.conrelid) AND (pc.conindid = pc2.conindid))))
     LEFT JOIN pg_namespace pn2 ON ((pn2.oid = pc2.connamespace)))
  WHERE (has_table_privilege(c.oid, 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER'::text) AND has_schema_privilege(pn.oid, 'USAGE'::text) AND (pn.nspname <> ALL (ARRAY['pg_catalog'::name, 'information_schema'::name, 'pg_toast'::name])));


ALTER TABLE sys.all_constraints OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6427 (class 1259 OID 15020)
-- Name: all_db_links; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.all_db_links AS
 SELECT
        CASE
            WHEN (e.lnkispublic = true) THEN 'PUBLIC'::text
            WHEN (e.lnkispublic = false) THEN quote_ident_redwood((pg_get_userbyid(e.lnkowner))::text)
            ELSE NULL::text
        END AS owner,
    upper((e.lnkname)::text) AS db_link,
        DECODE(  ((e.lnktype)::text)::character varying
            , ('0'::text)::character varying
            , ('REDWOOD'::text)::character varying
            , ('1'::text)::character varying
            , ('EDB'::text)::character varying
            , NULL::character varying
        ) AS type,
    quote_ident_redwood(e.lnkuser) AS username,
    e.lnkconnstr AS host
   FROM edb_dblink e
  WHERE ((e.lnkispublic = true) OR has_server_privilege(e.oid, 'USAGE'::text));


ALTER TABLE sys.all_db_links OWNER TO "mdt-mdm-edb-cjm-prd";

