--
-- TOC entry 6435 (class 1259 OID 15056)
-- Name: all_policies; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.all_policies AS
 SELECT quote_ident_redwood((ep.object_owner)::text) AS object_owner,
    quote_ident_redwood((ep.schema_name)::text) AS schema_name,
    quote_ident_redwood((ep.object_name)::text) AS object_name,
    ep.policy_group,
    quote_ident_redwood((ep.policy_name)::text) AS policy_name,
    quote_ident_redwood((ep.pf_owner)::text) AS pf_owner,
    quote_ident_redwood((ep.package)::text) AS package,
    quote_ident_redwood((ep.function)::text) AS function,
    ep.sel,
    ep.ins,
    ep.upd,
    ep.del,
    ep.idx,
    ep.chk_option,
    ep.enable,
    ep.static_policy,
    ep.policy_type,
    ep.long_predicate
   FROM ( SELECT
                CASE p.policykind
                    WHEN 'r'::"char" THEN pg_get_userbyid(objclass.relowner)
                    WHEN 'v'::"char" THEN pg_get_userbyid(objclass.relowner)
                    WHEN '='::"char" THEN pg_get_userbyid(objsyn.synowner)
                    ELSE NULL::name
                END AS object_owner,
                CASE p.policykind
                    WHEN 'r'::"char" THEN objclassschema.nspname
                    WHEN 'v'::"char" THEN objclassschema.nspname
                    WHEN '='::"char" THEN objsynschema.nspname
                    ELSE NULL::name
                END AS schema_name,
                CASE p.policykind
                    WHEN 'r'::"char" THEN objclass.relname
                    WHEN 'v'::"char" THEN objclass.relname
                    WHEN '='::"char" THEN objsyn.synname
                    ELSE NULL::name
                END AS object_name,
                CASE p.policykind
                    WHEN 'r'::"char" THEN (has_table_privilege(objclass.oid, 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER'::text) AND has_schema_privilege(objclassschema.oid, 'USAGE'::text))
                    WHEN 'v'::"char" THEN (has_table_privilege(objclass.oid, 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER'::text) AND has_schema_privilege(objclassschema.oid, 'USAGE'::text))
                    WHEN '='::"char" THEN ((objsynschema.nspname = 'public'::name) OR pg_has_role(objsyn.synowner, 'USAGE'::text))
                    ELSE NULL::boolean
                END AS can_access,
            ''::text AS policy_group,
            p.policyname AS policy_name,
                CASE
                    WHEN (proschema.nspparent = (0)::oid) THEN proschema.nspname
                    ELSE pkgschema.nspname
                END AS pf_owner,
                CASE
                    WHEN (proschema.nspparent = (0)::oid) THEN NULL::name
                    ELSE proschema.nspname
                END AS package,
            proc.proname AS function,
                CASE p.policyselect
                    WHEN true THEN 'YES'::text
                    ELSE 'NO'::text
                END AS sel,
                CASE p.policyinsert
                    WHEN true THEN 'YES'::text
                    ELSE 'NO'::text
                END AS ins,
                CASE p.policyupdate
                    WHEN true THEN 'YES'::text
                    ELSE 'NO'::text
                END AS upd,
                CASE p.policydelete
                    WHEN true THEN 'YES'::text
                    ELSE 'NO'::text
                END AS del,
                CASE p.policyindex
                    WHEN true THEN 'YES'::text
                    ELSE 'NO'::text
                END AS idx,
                CASE p.policyupdatecheck
                    WHEN true THEN 'YES'::text
                    ELSE 'NO'::text
                END AS chk_option,
                CASE p.policyenabled
                    WHEN true THEN 'YES'::text
                    ELSE 'NO'::text
                END AS enable,
                CASE p.policystatic
                    WHEN true THEN 'YES'::text
                    ELSE 'NO'::text
                END AS static_policy,
                CASE p.policytype
                    WHEN 1 THEN 'STATIC'::text
                    WHEN 2 THEN 'SHARED_STATIC'::text
                    WHEN 3 THEN 'CONTEXT_SENSITIVE'::text
                    WHEN 4 THEN 'SHARED_CONTEXT_SENSITIVE'::text
                    WHEN 5 THEN 'DYNAMIC'::text
                    ELSE 'UNKNOWN'::text
                END AS policy_type,
            'YES'::text AS long_predicate
           FROM (((((((edb_policy p
             JOIN pg_proc proc ON ((proc.oid = p.policyproc)))
             JOIN pg_namespace proschema ON ((proschema.oid = proc.pronamespace)))
             LEFT JOIN pg_namespace pkgschema ON ((pkgschema.oid = proschema.nspparent)))
             LEFT JOIN pg_class objclass ON ((objclass.oid = p.policyobject)))
             LEFT JOIN pg_synonym objsyn ON ((objsyn.oid = p.policyobject)))
             LEFT JOIN pg_namespace objclassschema ON ((objclassschema.oid = objclass.relnamespace)))
             LEFT JOIN pg_namespace objsynschema ON ((objsynschema.oid = objsyn.synnamespace)))) ep
  WHERE ((ep.can_access = true) AND (ep.schema_name <> ALL (ARRAY['pg_catalog'::name, 'information_schema'::name, 'pg_toast'::name])));


ALTER TABLE sys.all_policies OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6453 (class 1259 OID 15143)
-- Name: all_queue_tables; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.all_queue_tables AS
 SELECT quote_ident_redwood(((pg_get_userbyid(c.relowner))::character varying)::text) AS owner,
    quote_ident_redwood((qt.qtname)::text) AS queue_table,
        CASE
            WHEN (t.typname IS NULL) THEN 'RAW'::character varying
            ELSE 'OBJECT'::character varying
        END AS type,
    ((quote_ident_redwood((n.nspname)::text) || '.'::text) || quote_ident_redwood((t.typname)::text)) AS object_type,
        CASE qt.qtsort
            WHEN 'p'::"char" THEN 'PRIORITY'::character varying
            WHEN 'e'::"char" THEN 'ENQUEUE_TIME'::character varying
            WHEN 'P'::"char" THEN 'PRIORITY, ENQUEUE_TIME'::character varying
            WHEN 'E'::"char" THEN 'ENQUEUE_TIME, PRIORITY'::character varying
            ELSE 'NONE'::character varying
        END AS sort_order,
        CASE
            WHEN qt.qtmultiple_consumers THEN 'MULTIPLE'::character varying
            ELSE 'SINGLE'::character varying
        END AS recipients,
        CASE
            WHEN (qt.qtmessage_grouping = 0) THEN 'NONE'::character varying
            ELSE 'TRANSACTIONAL'::character varying
        END AS message_grouping,
    '9.6.0.0'::character varying AS compatible,
    (0)::numeric AS primary_instance,
    (0)::numeric AS secondary_instance,
    (1)::numeric AS owner_instance,
    ( SELECT (pg_description.description)::character varying AS description
           FROM pg_description
          WHERE ((pg_description.objoid = qt.oid) AND (pg_description.classoid = ('edb_queue_table'::regclass)::oid))) AS user_comment,
    'NO'::character varying AS secure
   FROM (((edb_queue_table qt
     LEFT JOIN pg_class c ON ((c.oid = qt.qtrelid)))
     LEFT JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
     LEFT JOIN pg_type t ON ((t.oid = qt.qpayloadtype)))
  WHERE (has_table_privilege(c.oid, 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER'::text) AND has_schema_privilege(n.oid, 'USAGE'::text) AND (n.nspname <> ALL (ARRAY['pg_catalog'::name, 'information_schema'::name, 'pg_toast'::name])));


ALTER TABLE sys.all_queue_tables OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6456 (class 1259 OID 15157)
-- Name: all_queues; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.all_queues AS
 SELECT quote_ident_redwood(((pg_get_userbyid(c.relowner))::character varying)::text) AS owner,
    quote_ident_redwood((q.aqname)::text) AS name,
    quote_ident_redwood((qt.qtname)::text) AS queue_table,
    q.oid AS qid,
        CASE q.aqtype
            WHEN 'e'::"char" THEN 'EXCEPTION_QUEUE'::character varying
            WHEN 'q'::"char" THEN 'NORMAL_QUEUE'::character varying
            ELSE NULL::character varying
        END AS queue_type,
    q.aqretries AS max_retries,
    q.aqretrydelay AS retry_delay,
        CASE
            WHEN q.aqcanenqueue THEN 'YES'::character varying
            ELSE 'NO'::character varying
        END AS enqueue_enabled,
        CASE
            WHEN q.aqcandequeue THEN 'YES'::character varying
            ELSE 'NO'::character varying
        END AS dequeue_enabled,
        CASE
            WHEN (q.aqretention = ('-1'::integer)::double precision) THEN 'FOREVER'::character varying
            ELSE (q.aqretention)::character varying
        END AS retention,
    ( SELECT (pg_description.description)::character varying AS description
           FROM pg_description
          WHERE ((pg_description.objoid = q.oid) AND (pg_description.classoid = ('edb_queue'::regclass)::oid))) AS user_comment,
    NULL::character varying AS network_name,
    'FALSE'::character varying AS sharded
   FROM (((edb_queue q
     LEFT JOIN pg_class c ON ((c.oid = q.aqrelid)))
     LEFT JOIN edb_queue_table qt ON ((qt.qtrelid = q.aqrelid)))
     LEFT JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
  WHERE (has_table_privilege(c.oid, 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER'::text) AND has_schema_privilege(n.oid, 'USAGE'::text) AND (n.nspname <> ALL (ARRAY['pg_catalog'::name, 'information_schema'::name, 'pg_toast'::name])));


