    (p.lt).line AS line,
    (p.lt).text AS text
   FROM ((( SELECT t.tgrelid,
            t.tgname,
            c.relnamespace,
            c.relowner,
            split_to_lines(pg_get_triggerdef(t.oid)) AS lt
           FROM pg_trigger t,
            pg_class c
          WHERE (t.tgrelid = c.oid)) p
     JOIN pg_namespace n ON ((n.oid = p.relnamespace)))
     JOIN pg_authid u ON ((u.oid = p.relowner)))
  WHERE (has_table_privilege(p.tgrelid, 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER'::text) AND has_schema_privilege(n.oid, 'USAGE'::text));


