            , ('character'::text)::character varying
            , ('CHAR'::text)::character varying
            , ('timestamp without time zone'::text)::character varying
            , ('DATE'::text)::character varying
            , ('time without time zone'::text)::character varying
            , ('TIME WITHOUT TIME ZONE'::text)::character varying
            , ('real'::text)::character varying
            , ('REAL'::text)::character varying
