            , ('BLOB'::text)::character varying
            , ('TEXT'::text)::character varying
            , ('CLOB'::text)::character varying
            , (isc.data_type)::character varying
        ) AS data_type,
    (isc.data_length)::numeric AS data_length,
    (isc.data_precision)::numeric AS data_precision,
    (isc.data_scale)::numeric AS data_scale,
    isc.nullable,
    (isc.column_id)::numeric AS column_id,
    (isc.data_default)::character varying AS data_default
   FROM ( SELECT pg_get_userbyid(c.relowner) AS owner,
            nc.nspname AS schema_name,
            c.relname AS table_name,
            a.attname AS column_name,
                CASE
                    WHEN (t.typtype = 'd'::"char") THEN
                    CASE
                        WHEN ((bt.typelem <> (0)::oid) AND (bt.typlen = '-1'::integer)) THEN 'ARRAY'::text
                        ELSE
                        CASE
                            WHEN (quote_ident(format_type(t.typbasetype, NULL::integer)) = format_type(t.typbasetype, NULL::integer)) THEN quote_ident_redwood(format_type(t.typbasetype, NULL::integer))
                            ELSE format_type(t.typbasetype, NULL::integer)
                        END
                    END
                    ELSE
                    CASE
                        WHEN ((t.typelem <> (0)::oid) AND (t.typlen = '-1'::integer)) THEN 'ARRAY'::text
                        ELSE
                        CASE
                            WHEN (quote_ident(format_type(a.atttypid, NULL::integer)) = format_type(a.atttypid, NULL::integer)) THEN quote_ident_redwood(format_type(a.atttypid, NULL::integer))
                            ELSE format_type(a.atttypid, NULL::integer)
                        END
                    END
                END AS data_type,
            information_schema._pg_char_max_length(information_schema._pg_truetypid(a.*, t.*), information_schema._pg_truetypmod(a.*, t.*)) AS data_length,
            information_schema._pg_numeric_precision(information_schema._pg_truetypid(a.*, t.*), information_schema._pg_truetypmod(a.*, t.*)) AS data_precision,
            information_schema._pg_numeric_scale(information_schema._pg_truetypid(a.*, t.*), information_schema._pg_truetypmod(a.*, t.*)) AS data_scale,
            a.attnum AS column_id,
                CASE
                    WHEN (a.attnotnull OR ((t.typtype = 'd'::"char") AND t.typnotnull)) THEN 'N'::character(1)
                    ELSE 'Y'::character(1)
                END AS nullable,
            pg_get_expr(ad.adbin, ad.adrelid) AS data_default
           FROM (((((pg_attribute a
             LEFT JOIN pg_attrdef ad ON (((a.attrelid = ad.adrelid) AND (a.attnum = ad.adnum))))
             JOIN (pg_class c
             JOIN pg_namespace nc ON ((c.relnamespace = nc.oid))) ON ((a.attrelid = c.oid)))
             JOIN (pg_type t
             JOIN pg_namespace nt ON ((t.typnamespace = nt.oid))) ON ((a.atttypid = t.oid)))
             LEFT JOIN (pg_type bt
             JOIN pg_namespace nbt ON ((bt.typnamespace = nbt.oid))) ON (((t.typtype = 'd'::"char") AND (t.typbasetype = bt.oid))))
             LEFT JOIN (pg_collation co
             JOIN pg_namespace nco ON ((co.collnamespace = nco.oid))) ON (((a.attcollation = co.oid) AND ((nco.nspname <> 'pg_catalog'::name) OR (co.collname <> 'default'::name)))))
          WHERE ((NOT pg_is_other_temp_schema(nc.oid)) AND (a.attnum > 0) AND (NOT a.attisdropped) AND (c.relkind = 'v'::"char") AND has_column_privilege(c.oid, a.attnum, 'SELECT, INSERT, UPDATE, REFERENCES'::text) AND has_schema_privilege(nc.oid, 'USAGE'::text) AND (nc.nspname <> ALL (ARRAY['pg_catalog'::name, 'information_schema'::name, 'pg_toast'::name])))) isc
  ORDER BY (quote_ident_redwood((isc.owner)::text))::character varying, (quote_ident_redwood((isc.schema_name)::text))::character varying;


