--

CREATE VIEW sys.all_tab_partitions AS
 SELECT quote_ident_redwood((pg_get_userbyid(class2.relowner))::text) AS table_owner,
    quote_ident_redwood((ns.nspname)::text) AS schema_name,
    quote_ident_redwood((class2.relname)::text) AS table_name,
        CASE class.relkind
            WHEN 'p'::"char" THEN 'YES'::text
            ELSE 'NO'::text
        END AS composite,
    quote_ident_redwood(class.relpartname) AS partition_name,
    ( SELECT count(*) AS count
           FROM pg_inherits inh2
          WHERE (inh2.inhparent = inh.inhrelid)) AS subpartition_count,
    pg_get_expr(class.relpartbound, inh.inhrelid) AS high_value,
    length(pg_get_expr(class.relpartbound, inh.inhrelid)) AS high_value_length,
    NULL::numeric AS partition_position,
    quote_ident_redwood((ts.spcname)::text) AS tablespace_name,
    (0)::numeric AS pct_free,
    (0)::numeric AS pct_used,
    (0)::numeric AS ini_trans,
    (0)::numeric AS max_trans,
    NULL::numeric AS initial_extent,
    NULL::numeric AS next_extent,
    (0)::numeric AS min_extent,
    (0)::numeric AS max_extent,
    (0)::numeric AS pct_increase,
    NULL::numeric AS freelists,
    NULL::numeric AS freelist_groups,
    'YES'::character varying(7) AS logging,
    'NONE'::character varying(8) AS compression,
    (class.reltuples)::numeric AS num_rows,
    class.relpages AS blocks,
    NULL::numeric AS empty_blocks,
    NULL::numeric AS avg_space,
    NULL::numeric AS chain_cnt,
    NULL::numeric AS avg_row_len,
    NULL::numeric AS sample_size,
    NULL::timestamp without time zone AS last_analyzed,
    NULL::character varying(7) AS buffer_pool,
    'YES'::character varying(3) AS global_stats,
    'NO'::character varying(3) AS user_stats,
    (inh.inhrelid)::regclass AS backing_table
   FROM ((((pg_inherits inh
     JOIN pg_class class ON ((class.oid = inh.inhrelid)))
     JOIN pg_class class2 ON ((class2.oid = inh.inhparent)))
     JOIN pg_namespace ns ON ((ns.oid = class2.relnamespace)))
     LEFT JOIN pg_tablespace ts ON ((ts.oid = class.reltablespace)))
  WHERE (has_table_privilege(class2.oid, 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER'::text) AND has_schema_privilege(ns.oid, 'USAGE'::text) AND (ns.nspname <> ALL (ARRAY['pg_catalog'::name, 'information_schema'::name, 'pg_toast'::name])) AND (class2.relkind = 'p'::"char") AND (class2.relispartition = false));


ALTER TABLE sys.all_tab_partitions OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6444 (class 1259 OID 15100)
-- Name: all_tab_subpartitions; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.all_tab_subpartitions AS
 SELECT quote_ident_redwood((pg_get_userbyid(class2.relowner))::text) AS table_owner,
    quote_ident_redwood((ns.nspname)::text) AS schema_name,
    quote_ident_redwood((class2.relname)::text) AS table_name,
    ( SELECT quote_ident_redwood(pg_class.relpartname) AS quote_ident_redwood
           FROM pg_class
          WHERE (pg_class.oid = inh1.inhparent)) AS partition_name,
    quote_ident_redwood(class.relpartname) AS subpartition_name,
    pg_get_expr(class.relpartbound, inh1.inhrelid) AS high_value,
    length(pg_get_expr(class.relpartbound, inh1.inhrelid)) AS high_value_length,
    NULL::numeric AS subpartition_position,
    quote_ident_redwood((ts.spcname)::text) AS tablespace_name,
    (0)::numeric AS pct_free,
    (0)::numeric AS pct_used,
    (0)::numeric AS ini_trans,
    (0)::numeric AS max_trans,
    NULL::numeric AS initial_extent,
    NULL::numeric AS next_extent,
    (0)::numeric AS min_extent,
    (0)::numeric AS max_extent,
    (0)::numeric AS pct_increase,
    NULL::numeric AS freelists,
    NULL::numeric AS freelist_groups,
    'YES'::character varying(7) AS logging,
    'NONE'::character varying(8) AS compression,
    (class.reltuples)::numeric AS num_rows,
    class.relpages AS blocks,
    NULL::numeric AS empty_blocks,
    NULL::numeric AS avg_space,
    NULL::numeric AS chain_cnt,
    NULL::numeric AS avg_row_len,
    NULL::numeric AS sample_size,
    NULL::timestamp without time zone AS last_analyzed,
    NULL::character varying(7) AS buffer_pool,
    'YES'::character varying(3) AS global_stats,
    'NO'::character varying(3) AS user_stats,
    (inh1.inhrelid)::regclass AS backing_table
   FROM (((((pg_inherits inh1
     JOIN pg_inherits inh2 ON ((inh1.inhparent = inh2.inhrelid)))
     JOIN pg_class class ON ((class.oid = inh1.inhrelid)))
     JOIN pg_class class2 ON ((class2.oid = inh2.inhparent)))
     JOIN pg_namespace ns ON ((ns.oid = class2.relnamespace)))
     LEFT JOIN pg_tablespace ts ON ((ts.oid = class.reltablespace)))
  WHERE (has_table_privilege(class2.oid, 'SELECT, INSERT, UPDATE, DELETE, TRUNCATE, REFERENCES, TRIGGER'::text) AND has_schema_privilege(ns.oid, 'USAGE'::text) AND (ns.nspname <> ALL (ARRAY['pg_catalog'::name, 'information_schema'::name, 'pg_toast'::name])) AND (class2.relkind = 'p'::"char") AND (class2.relispartition = false));


ALTER TABLE sys.all_tab_subpartitions OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6380 (class 1259 OID 14802)
-- Name: dba_users; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_users AS
 SELECT quote_ident_redwood((pga.rolname)::text) AS username,
    pga.oid AS user_id,
    (pga.rolpassword)::character varying(30) AS password,
    (edb_get_role_status(pga.oid))::character varying(32) AS account_status,
    (
        CASE
            WHEN (edb_get_role_status(pga.oid) !~~ '%LOCKED%'::text) THEN NULL::timestamp with time zone
            ELSE pga.rollockdate
        END)::timestamp without time zone AS lock_date,
    (edb_get_password_expiry_date(pga.oid))::timestamp without time zone AS expiry_date,
    quote_ident_redwood(((pgt.spcname)::character varying(30))::text) AS default_tablespace,
    ''::character varying(30) AS temporary_tablespace,
    NULL::timestamp without time zone AS created,
    (
        CASE
            WHEN (prf.prfname = 'default'::name) THEN 'DEFAULT'::text
            ELSE quote_ident_redwood((prf.prfname)::text)
        END)::character varying(30) AS profile,
    NULL::character varying(30) AS initial_rsrc_consumer_group,
    NULL::character varying(4000) AS external_name
   FROM pg_authid pga,
    pg_database pgd,
    pg_tablespace pgt,
    edb_profile prf
  WHERE ((pgd.datname = current_database()) AND (pgd.dattablespace = pgt.oid) AND (pga.rolprofile = prf.oid));


ALTER TABLE sys.dba_users OWNER TO "mdt-mdm-edb-cjm-prd";

