--
-- TOC entry 6390 (class 1259 OID 14848)
-- Name: dba_all_tables; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_all_tables AS
 SELECT quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS owner,
    quote_ident_redwood((n.nspname)::text) AS schema_name,
    quote_ident_redwood((c.relname)::text) AS table_name,
    quote_ident_redwood((t.spcname)::text) AS tablespace_name,
    'VALID'::character varying(5) AS status,
        CASE
            WHEN (n.nspname ~~ 'pg_temp_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM ((pg_class c
     LEFT JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
     LEFT JOIN pg_tablespace t ON ((t.oid = c.reltablespace)))
  WHERE (c.relkind = ANY (ARRAY['r'::"char", 'p'::"char"]));


ALTER TABLE sys.dba_all_tables OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6408 (class 1259 OID 14932)
-- Name: dba_cons_columns; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_cons_columns AS
 SELECT quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS owner,
    quote_ident_redwood((pn.nspname)::text) AS schema_name,
    quote_ident_redwood((pc.conname)::text) AS constraint_name,
    quote_ident_redwood((c.relname)::text) AS table_name,
    quote_ident_redwood((pa.attname)::text) AS column_name,
    ("position"."position")::smallint AS "position",
    quote_ident_redwood(pg_get_constraintdef(pc.oid)) AS constraint_def
   FROM (((((pg_attribute pa
     JOIN pg_constraint pc ON (((pc.conrelid = pa.attrelid) AND (pc.contype = ANY (ARRAY['f'::"char", 'u'::"char", 'p'::"char", 'c'::"char"])))))
     JOIN pg_namespace pn ON ((pn.oid = pc.connamespace)))
     LEFT JOIN pg_class c ON ((c.oid = pc.conrelid)))
     LEFT JOIN pg_index ind ON ((ind.indexrelid = pc.conindid)))
     LEFT JOIN LATERAL generate_series(1,
        CASE
            WHEN (pc.contype = ANY (ARRAY['f'::"char", 'p'::"char", 'u'::"char"])) THEN array_upper(pc.conkey, 1)
            ELSE 0
        END) "position"("position") ON (true))
  WHERE (((pc.contype = 'f'::"char") AND (pa.attnum = pc.conkey[( SELECT key_i.key_i
           FROM generate_subscripts(pc.confkey, 1) key_i(key_i)
          WHERE (pc.confkey[key_i.key_i] = ind.indkey[("position"."position" - 1)]))])) OR ((pc.contype = ANY (ARRAY['u'::"char", 'p'::"char"])) AND (pa.attnum = pc.conkey["position"."position"])) OR ((pc.contype = 'c'::"char") AND (pa.attnum = ANY (pc.conkey))));


ALTER TABLE sys.dba_cons_columns OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6387 (class 1259 OID 14834)
-- Name: dba_constraints; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_constraints AS
 SELECT quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS owner,
    quote_ident_redwood((pn.nspname)::text) AS schema_name,
    quote_ident_redwood((pc.conname)::text) AS constraint_name,
    quote_ident_redwood((pc.contype)::text) AS constraint_type,
    quote_ident_redwood((c.relname)::text) AS table_name,
    quote_ident_redwood(pc.consrc) AS search_condition,
        CASE
            WHEN (pc.contype = 'f'::"char") THEN quote_ident_redwood((pn2.nspname)::text)
            ELSE NULL::text
        END AS r_owner,
        CASE
            WHEN (pc.contype = 'f'::"char") THEN quote_ident_redwood((pc2.conname)::text)
            ELSE NULL::text
        END AS r_constraint_name,
    quote_ident_redwood((pc.confdeltype)::text) AS delete_rule,
    pc.condeferrable AS "deferrable",
    pc.condeferred AS deferred,
    quote_ident_redwood((ni.nspname)::text) AS index_owner,
    quote_ident_redwood((i.relname)::text) AS index_name,
    pg_get_constraintdef(pc.oid) AS constraint_def
   FROM ((((((pg_constraint pc
     LEFT JOIN pg_namespace pn ON ((pn.oid = pc.connamespace)))
     LEFT JOIN pg_class c ON ((c.oid = pc.conrelid)))
     LEFT JOIN pg_class i ON ((i.oid = pc.conindid)))
     LEFT JOIN pg_namespace ni ON ((i.relnamespace = ni.oid)))
     LEFT JOIN pg_constraint pc2 ON (((pc.contype = 'f'::"char") AND (pc.confrelid = pc2.conrelid) AND (pc.conindid = pc2.conindid))))
     LEFT JOIN pg_namespace pn2 ON ((pn2.oid = pc2.connamespace)));


ALTER TABLE sys.dba_constraints OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6426 (class 1259 OID 15016)
-- Name: dba_db_links; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_db_links AS
 SELECT
        CASE
            WHEN (e.lnkispublic = true) THEN 'PUBLIC'::text
            WHEN (e.lnkispublic = false) THEN quote_ident_redwood((pg_get_userbyid(e.lnkowner))::text)
            ELSE NULL::text
        END AS owner,
    upper((e.lnkname)::text) AS db_link,
        DECODE(  ((e.lnktype)::text)::character varying
            , ('0'::text)::character varying
            , ('REDWOOD'::text)::character varying
            , ('1'::text)::character varying
            , ('EDB'::text)::character varying
            , NULL::character varying
        ) AS type,
    quote_ident_redwood(e.lnkuser) AS username,
    e.lnkconnstr AS host
   FROM edb_dblink e;


ALTER TABLE sys.dba_db_links OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6414 (class 1259 OID 14960)
-- Name: dba_ind_columns; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_ind_columns AS
 SELECT quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS index_owner,
    quote_ident_redwood((n.nspname)::text) AS schema_name,
    quote_ident_redwood((i.relname)::text) AS index_name,
    quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS table_owner,
    quote_ident_redwood((c.relname)::text) AS table_name,
    quote_ident_redwood((j.attname)::text) AS column_name,
    j.attnum AS column_position,
    j.attlen AS column_length,
    (
        CASE
            WHEN (j.atttypid = (18)::oid) THEN (j.attlen)::integer
            ELSE 0
        END)::numeric AS char_length,
    'Y'::character(1) AS descend
   FROM (((((pg_index x
     JOIN pg_class c ON ((c.oid = x.indrelid)))
     JOIN pg_class i ON ((i.oid = x.indexrelid)))
     JOIN pg_attribute j ON ((j.attrelid = i.oid)))
     LEFT JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
     LEFT JOIN pg_tablespace t ON ((t.oid = i.reltablespace)))
  WHERE ((c.relkind = 'r'::"char") AND (i.relkind = 'i'::"char"))
  ORDER BY i.relname, j.attnum;


ALTER TABLE sys.dba_ind_columns OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6411 (class 1259 OID 14946)
-- Name: dba_indexes; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_indexes AS
 SELECT quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS owner,
    quote_ident_redwood((n.nspname)::text) AS schema_name,
    quote_ident_redwood((i.relname)::text) AS index_name,
    'BTREE'::text AS index_type,
    quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS table_owner,
    quote_ident_redwood((c.relname)::text) AS table_name,
    'TABLE'::text AS table_type,
        CASE
            WHEN (x.indisunique = true) THEN 'UNIQUE'::text
            ELSE 'NONUNIQUE'::text
        END AS uniqueness,
    'N'::character(1) AS compression,
    quote_ident_redwood((t.spcname)::text) AS tablespace_name,
    'LOGGING'::text AS logging,
        CASE
            WHEN (x.indisvalid = true) THEN 'VALID'::text
            ELSE 'INVALID'::text
        END AS status,
    'NO'::character(3) AS partitioned,
    (
        CASE
            WHEN (n.nspname ~~ 'pg_temp_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END)::character(1) AS temporary,
    'N'::character(1) AS secondary,
    'NO'::character(3) AS join_index,
    'NO'::character(3) AS dropped
   FROM ((((pg_index x
     JOIN pg_class c ON ((c.oid = x.indrelid)))
     JOIN pg_class i ON ((i.oid = x.indexrelid)))
     LEFT JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
     LEFT JOIN pg_tablespace t ON ((t.oid = i.reltablespace)))
  WHERE ((c.relkind = 'r'::"char") AND (i.relkind = 'i'::"char"));


ALTER TABLE sys.dba_indexes OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6423 (class 1259 OID 15002)
-- Name: dba_sequences; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_sequences AS
 SELECT quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS sequence_owner,
    quote_ident_redwood((n.nspname)::text) AS schema_name,
    quote_ident_redwood((c.relname)::text) AS sequence_name,
    (showseq(((c.oid)::regclass)::oid)).min_value AS min_value,
    (showseq(((c.oid)::regclass)::oid)).max_value AS max_value,
    (showseq(((c.oid)::regclass)::oid)).increment_by AS increment_by,
    (showseq(((c.oid)::regclass)::oid)).cycle_flag AS cycle_flag,
    (showseq(((c.oid)::regclass)::oid)).order_flag AS order_flag,
    (showseq(((c.oid)::regclass)::oid)).cache_size AS cache_size,
    (showseq(((c.oid)::regclass)::oid)).last_number AS last_number
   FROM (pg_class c
     LEFT JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
  WHERE (c.relkind = 'S'::"char");


ALTER TABLE sys.dba_sequences OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6402 (class 1259 OID 14904)
-- Name: dba_synonyms; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_synonyms AS
 SELECT quote_ident_redwood((pg_get_userbyid(sy.synowner))::text) AS owner,
    quote_ident_redwood((pnname.nspname)::text) AS schema_name,
    quote_ident_redwood((sy.synname)::text) AS synonym_name,
    quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS table_owner,
    quote_ident_redwood((sy.synobjschema)::text) AS table_schema_name,
    quote_ident_redwood((sy.synobjname)::text) AS table_name,
    quote_ident_redwood((sy.synlink)::text) AS db_link
   FROM (((pg_synonym sy
     LEFT JOIN pg_namespace pnoid ON (((pnoid.nspname = sy.synobjschema) AND (pnoid.nspparent = (0)::oid))))
     LEFT JOIN pg_class c ON (((c.relname = sy.synobjname) AND (c.relnamespace = pnoid.oid))))
     LEFT JOIN pg_namespace pnname ON ((pnname.oid = sy.synnamespace)));


ALTER TABLE sys.dba_synonyms OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6384 (class 1259 OID 14820)
-- Name: dba_tables; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_tables AS
 SELECT quote_ident_redwood(((pg_get_userbyid(c.relowner))::character varying)::text) AS owner,
    quote_ident_redwood((n.nspname)::text) AS schema_name,
    quote_ident_redwood((c.relname)::text) AS table_name,
    quote_ident_redwood((t.spcname)::text) AS tablespace_name,
    'VALID'::character varying(5) AS status,
    (
        CASE
            WHEN (n.nspname ~~ 'pg_temp_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END)::character(1) AS temporary
   FROM ((pg_class c
     LEFT JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
     LEFT JOIN pg_tablespace t ON ((t.oid = c.reltablespace)))
  WHERE (c.relkind = ANY (ARRAY['r'::"char", 'p'::"char"]));


ALTER TABLE sys.dba_tables OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6393 (class 1259 OID 14862)
-- Name: dba_triggers; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_triggers AS
 SELECT quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS owner,
    quote_ident_redwood((n.nspname)::text) AS schema_name,
    quote_ident_redwood((t.tgname)::text) AS trigger_name,
    ((
        CASE
            WHEN (((t.tgtype)::integer & 2) = 2) THEN 'BEFORE'::text
            ELSE 'AFTER'::text
        END || ' '::text) ||
        CASE
            WHEN (((t.tgtype)::integer & 1) = 1) THEN 'ROW'::text
            ELSE 'STATEMENT'::text
        END) AS trigger_type,
    concat_ws(' OR '::text,
        CASE
            WHEN (((t.tgtype)::integer & 4) = 4) THEN 'INSERT'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (((t.tgtype)::integer & 16) = 16) THEN 'UPDATE'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (((t.tgtype)::integer & 8) = 8) THEN 'DELETE'::text
            ELSE NULL::text
        END,
        CASE
            WHEN (((t.tgtype)::integer & 32) = 32) THEN 'TRUNCATE'::text
            ELSE NULL::text
        END) AS triggering_event,
    quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS table_owner,
    'TABLE'::text AS base_object_type,
    quote_ident_redwood((c.relname)::text) AS table_name,
    'REFERENCING NEW AS NEW OLD AS OLD'::text AS referencing_names,
        CASE
            WHEN (t.tgenabled <> 'D'::"char") THEN 'ENABLED'::text
            ELSE 'DISABLED'::text
        END AS status,
    'see TRIGGER_BODY for text'::text AS description,
    pg_get_triggerdef(t.oid) AS trigger_body,
    "substring"(pg_get_triggerdef(t.oid), ("position"("substring"(pg_get_triggerdef(t.oid), 48), 'EXECUTE PROCEDURE'::text) + 47)) AS action_statement
   FROM pg_namespace n,
    pg_class c,
    pg_trigger t
  WHERE ((n.oid = c.relnamespace) AND (c.oid = t.tgrelid) AND (((t.tgtype)::integer & 60) <> 0) AND (t.tgconstraint = (0)::oid) AND (NOT pg_is_other_temp_schema(n.oid)));


ALTER TABLE sys.dba_triggers OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6417 (class 1259 OID 14974)
-- Name: dba_types; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_types AS
 SELECT quote_ident_redwood((pg_get_userbyid(t.typowner))::text) AS owner,
    quote_ident_redwood((n.nspname)::text) AS schema_name,
    quote_ident_redwood((t.typname)::text) AS type_name,
    t.oid AS type_oid,
        CASE
            WHEN (t.typtype = 'c'::"char") THEN 'OBJECT'::text
            WHEN (t.typtype = ANY (ARRAY['A'::"char", 'N'::"char", 'V'::"char"])) THEN 'COLLECTION'::text
            ELSE 'OTHER'::text
        END AS typecode,
        CASE
            WHEN (c.relkind = 'c'::"char") THEN (c.relnatts)::integer
            ELSE 0
        END AS attributes
   FROM ((pg_type t
     LEFT JOIN pg_namespace n ON ((n.oid = t.typnamespace)))
     LEFT JOIN pg_class c ON ((t.typrelid = c.oid)))
  WHERE ((NOT ((t.typelem <> (0)::oid) AND (t.typlen = '-1'::integer) AND (t.typarray = (0)::oid))) AND ((c.relkind IS NULL) OR (c.relkind = 'c'::"char")) AND (NOT (n.nspname IN ( SELECT edb_package.pkgname
           FROM edb_package))));


