-- Name: dba_views; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_views AS
 SELECT quote_ident_redwood((pg_get_userbyid(c.relowner))::text) AS owner,
    quote_ident_redwood((n.nspname)::text) AS schema_name,
    quote_ident_redwood((c.relname)::text) AS view_name,
