--
-- TOC entry 6431 (class 1259 OID 15037)
-- Name: dba_objects; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_objects AS
 SELECT dba_indexes.owner,
    dba_indexes.schema_name,
    dba_indexes.index_name AS object_name,
    'INDEX'::text AS object_type,
    (dba_indexes.status)::character varying AS status,
        CASE
            WHEN (dba_indexes.schema_name ~~ 'PG_TEMP_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM dba_indexes
UNION ALL
 SELECT dba_sequences.sequence_owner AS owner,
    dba_sequences.schema_name,
    dba_sequences.sequence_name AS object_name,
    'SEQUENCE'::text AS object_type,
    'VALID'::character varying AS status,
        CASE
            WHEN (dba_sequences.schema_name ~~ 'PG_TEMP_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM dba_sequences
UNION ALL
 SELECT dba_tables.owner,
    dba_tables.schema_name,
    dba_tables.table_name AS object_name,
    'TABLE'::text AS object_type,
    dba_tables.status,
        CASE
            WHEN (dba_tables.schema_name ~~ 'PG_TEMP_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM dba_tables
UNION ALL
 SELECT dba_synonyms.owner,
    dba_synonyms.schema_name,
    dba_synonyms.synonym_name AS object_name,
    'SYNONYM'::text AS object_type,
    'VALID'::character varying AS status,
        CASE
            WHEN (dba_synonyms.schema_name ~~ 'PG_TEMP_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM dba_synonyms
UNION ALL
 SELECT dba_views.owner,
    dba_views.schema_name,
    dba_views.view_name AS object_name,
    'VIEW'::text AS object_type,
    'VALID'::character varying AS status,
        CASE
            WHEN (dba_views.schema_name ~~ 'PG_TEMP_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM dba_views
UNION ALL
 SELECT quote_ident_redwood((pg_get_userbyid(pr.proowner))::text) AS owner,
    quote_ident_redwood((ns.nspname)::text) AS schema_name,
    quote_ident_redwood((pr.proname)::text) AS object_name,
    'PROCEDURE'::text AS object_type,
    'VALID'::character varying AS status,
        CASE
            WHEN (ns.nspname ~~ 'pg_temp_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM pg_proc pr,
    pg_namespace ns,
    pg_language ln,
    pg_type tp
  WHERE ((ns.oid = pr.pronamespace) AND (ln.oid = pr.prolang) AND (pr.pronamespace = ns.oid) AND (pr.prorettype = tp.oid) AND (pr.protype = '1'::"char") AND (ns.nspparent = (0)::oid) AND (tp.typname <> 'trigger'::name))
UNION ALL
 SELECT quote_ident_redwood((pg_get_userbyid(pr.proowner))::text) AS owner,
    quote_ident_redwood((ns.nspname)::text) AS schema_name,
    quote_ident_redwood((pr.proname)::text) AS object_name,
    'FUNCTION'::text AS object_type,
    'VALID'::character varying AS status,
        CASE
            WHEN (ns.nspname ~~ 'pg_temp_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM pg_proc pr,
    pg_namespace ns,
    pg_language ln,
    pg_type tp
  WHERE ((ns.oid = pr.pronamespace) AND (ln.oid = pr.prolang) AND (pr.pronamespace = ns.oid) AND (pr.prorettype = tp.oid) AND (pr.protype = '0'::"char") AND (ns.nspparent = (0)::oid) AND (tp.typname <> 'trigger'::name))
UNION ALL
 SELECT quote_ident_redwood((pg_get_userbyid(pr.pkgowner))::text) AS owner,
    quote_ident_redwood((ns.nspname)::text) AS schema_name,
    quote_ident_redwood((pr.pkgname)::text) AS object_name,
    'PACKAGE'::text AS object_type,
    'VALID'::character varying AS status,
        CASE
            WHEN (ns.nspname ~~ 'pg_temp_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM edb_package pr,
    pg_namespace ns
  WHERE ((ns.oid = pr.pkgnamespace) AND (pr.pkgnamespace = ns.oid))
UNION ALL
 SELECT quote_ident_redwood((pg_get_userbyid(pr.pkgowner))::text) AS owner,
    quote_ident_redwood((ns.nspname)::text) AS schema_name,
    quote_ident_redwood((pr.pkgname)::text) AS object_name,
    'PACKAGE BODY'::text AS object_type,
    'VALID'::character varying AS status,
        CASE
            WHEN (ns.nspname ~~ 'pg_temp_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM edb_package pr,
    pg_namespace ns
  WHERE ((ns.oid = pr.pkgnamespace) AND (pr.pkgnamespace = ns.oid) AND (pr.pkgbodysrc IS NOT NULL))
UNION ALL
 SELECT dba_triggers.owner,
    dba_triggers.schema_name,
    dba_triggers.trigger_name AS object_name,
    'TRIGGER'::text AS object_type,
    'VALID'::character varying AS status,
        CASE
            WHEN (dba_triggers.schema_name ~~ 'PG_TEMP_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM dba_triggers
UNION ALL
 SELECT dba_types.owner,
    dba_types.schema_name,
    dba_types.type_name AS object_name,
    'TYPE'::text AS object_type,
    'VALID'::character varying AS status,
        CASE
            WHEN (dba_types.schema_name ~~ 'PG_TEMP_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM dba_types
UNION ALL
 SELECT dba_types.owner,
    dba_types.schema_name,
    dba_types.type_name AS object_name,
    'TYPE BODY'::text AS object_type,
    'VALID'::character varying AS status,
        CASE
            WHEN (dba_types.schema_name ~~ 'PG_TEMP_%'::text) THEN 'Y'::text
            ELSE 'N'::text
        END AS temporary
   FROM dba_types,
