  WHERE ((dba_types.type_oid = pg_namespace.nspobjecttype) AND (pg_namespace.nspbodysrc IS NOT NULL));


ALTER TABLE sys.dba_objects OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6446 (class 1259 OID 15110)
-- Name: dba_part_key_columns; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_part_key_columns AS
 SELECT quote_ident_redwood((pg_get_userbyid(s.relowner))::text) AS owner,
    quote_ident_redwood((s.rootschema)::text) AS schema_name,
    quote_ident_redwood((s.rootrelname)::text) AS name,
    'TABLE'::character(5) AS object_type,
    quote_ident_redwood((a.attname)::text) AS column_name,
    (s.ordinal + 1) AS column_position
   FROM (( SELECT pd.partrelid,
            pd.partattrs,
            generate_subscripts(pd.partattrs, 1) AS ordinal,
            ns.nspname AS rootschema,
            class.relname AS rootrelname,
            class.relowner
           FROM ((pg_partitioned_table pd
             JOIN pg_class class ON ((class.oid = pd.partrelid)))
             JOIN pg_namespace ns ON ((ns.oid = class.relnamespace)))
          WHERE ((class.relkind = 'p'::"char") AND (class.relispartition = false))) s
     JOIN pg_attribute a ON (((a.attrelid = s.partrelid) AND (a.attnum = s.partattrs[s.ordinal]))))
  ORDER BY s.rootrelname, s.ordinal;


ALTER TABLE sys.dba_part_key_columns OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6437 (class 1259 OID 15065)
-- Name: dba_part_tables; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_part_tables AS
 SELECT quote_ident_redwood((pg_get_userbyid(class.relowner))::text) AS owner,
    quote_ident_redwood((ns.nspname)::text) AS schema_name,
    quote_ident_redwood((class.relname)::text) AS table_name,
        CASE pd.partstrat
            WHEN 'r'::"char" THEN 'RANGE'::text
            WHEN 'l'::"char" THEN 'LIST'::text
            WHEN 'h'::"char" THEN 'HASH'::text
            ELSE 'UNKNOWN'::text
        END AS partitioning_type,
    nvl((( SELECT
                CASE pd2.partstrat
                    WHEN 'r'::"char" THEN 'RANGE'::text
                    WHEN 'l'::"char" THEN 'LIST'::text
                    WHEN 'h'::"char" THEN 'HASH'::text
                    ELSE 'UNKNOWN'::text
                END AS "case"
           FROM (pg_inherits inh
             JOIN pg_partitioned_table pd2 ON ((pd2.partrelid = inh.inhrelid)))
          WHERE (inh.inhparent = pd.partrelid)
         LIMIT 1))::character varying, 'NONE'::character varying) AS subpartitioning_type,
    ( SELECT count(*) AS count
           FROM pg_inherits
          WHERE (pg_inherits.inhparent = pd.partrelid)) AS partition_count,
    0 AS def_subpartition_count,
    pd.partnatts AS partitioning_key_count,
    ( SELECT pd2.partnatts
           FROM (pg_inherits inh
             JOIN pg_partitioned_table pd2 ON ((pd2.partrelid = inh.inhrelid)))
          WHERE (inh.inhparent = pd.partrelid)
         LIMIT 1) AS subpartitioning_key_count,
    'VALID'::character varying(8) AS status,
    NULL::character varying(30) AS def_tablespace_name,
    NULL::numeric AS def_pct_free,
    NULL::numeric AS def_pct_used,
    NULL::numeric AS def_ini_trans,
    NULL::numeric AS def_max_trans,
    NULL::character varying(40) AS def_initial_extent,
    NULL::character varying(40) AS def_next_extent,
    NULL::character varying(40) AS def_min_extents,
    NULL::character varying(40) AS def_max_extents,
    NULL::character varying(40) AS def_pct_increase,
    NULL::numeric AS def_freelists,
    NULL::numeric AS def_freelist_groups,
    'YES'::character varying(7) AS def_logging,
    'NONE'::character varying(8) AS def_compression,
    'DEFAULT'::character varying(7) AS def_buffer_pool,
    NULL::character varying(30) AS ref_ptn_constraint_name,
    NULL::character varying(1000) AS "interval"
   FROM ((pg_partitioned_table pd
     JOIN pg_class class ON ((class.oid = pd.partrelid)))
     JOIN pg_namespace ns ON ((ns.oid = class.relnamespace)))
  WHERE ((class.relkind = 'p'::"char") AND (class.relispartition = false));


ALTER TABLE sys.dba_part_tables OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6434 (class 1259 OID 15051)
-- Name: dba_policies; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_policies AS
 SELECT quote_ident_redwood((
        CASE p.policykind
            WHEN 'r'::"char" THEN pg_get_userbyid(objclass.relowner)
            WHEN 'v'::"char" THEN pg_get_userbyid(objclass.relowner)
            WHEN '='::"char" THEN pg_get_userbyid(objsyn.synowner)
            ELSE NULL::name
        END)::text) AS object_owner,
    quote_ident_redwood((
        CASE p.policykind
            WHEN 'r'::"char" THEN objclassschema.nspname
            WHEN 'v'::"char" THEN objclassschema.nspname
            WHEN '='::"char" THEN objsynschema.nspname
            ELSE NULL::name
        END)::text) AS schema_name,
    quote_ident_redwood((
        CASE p.policykind
            WHEN 'r'::"char" THEN objclass.relname
            WHEN 'v'::"char" THEN objclass.relname
            WHEN '='::"char" THEN objsyn.synname
            ELSE NULL::name
        END)::text) AS object_name,
    ''::text AS policy_group,
    quote_ident_redwood((p.policyname)::text) AS policy_name,
    quote_ident_redwood((
        CASE
            WHEN (proschema.nspparent = (0)::oid) THEN proschema.nspname
            ELSE pkgschema.nspname
        END)::text) AS pf_owner,
    quote_ident_redwood((
        CASE
            WHEN (proschema.nspparent = (0)::oid) THEN NULL::name
            ELSE proschema.nspname
        END)::text) AS package,
    quote_ident_redwood((proc.proname)::text) AS function,
        CASE p.policyselect
            WHEN true THEN 'YES'::text
            ELSE 'NO'::text
        END AS sel,
        CASE p.policyinsert
            WHEN true THEN 'YES'::text
            ELSE 'NO'::text
        END AS ins,
        CASE p.policyupdate
            WHEN true THEN 'YES'::text
            ELSE 'NO'::text
        END AS upd,
        CASE p.policydelete
            WHEN true THEN 'YES'::text
            ELSE 'NO'::text
        END AS del,
        CASE p.policyindex
            WHEN true THEN 'YES'::text
            ELSE 'NO'::text
        END AS idx,
        CASE p.policyupdatecheck
            WHEN true THEN 'YES'::text
            ELSE 'NO'::text
        END AS chk_option,
        CASE p.policyenabled
            WHEN true THEN 'YES'::text
            ELSE 'NO'::text
        END AS enable,
        CASE p.policystatic
            WHEN true THEN 'YES'::text
            ELSE 'NO'::text
        END AS static_policy,
        CASE p.policytype
            WHEN 1 THEN 'STATIC'::text
            WHEN 2 THEN 'SHARED_STATIC'::text
            WHEN 3 THEN 'CONTEXT_SENSITIVE'::text
            WHEN 4 THEN 'SHARED_CONTEXT_SENSITIVE'::text
            WHEN 5 THEN 'DYNAMIC'::text
            ELSE 'UNKNOWN'::text
        END AS policy_type,
    'YES'::text AS long_predicate
   FROM (((((((edb_policy p
     JOIN pg_proc proc ON ((proc.oid = p.policyproc)))
     JOIN pg_namespace proschema ON ((proschema.oid = proc.pronamespace)))
     LEFT JOIN pg_namespace pkgschema ON ((pkgschema.oid = proschema.nspparent)))
     LEFT JOIN pg_class objclass ON ((objclass.oid = p.policyobject)))
     LEFT JOIN pg_synonym objsyn ON ((objsyn.oid = p.policyobject)))
     LEFT JOIN pg_namespace objclassschema ON ((objclassschema.oid = objclass.relnamespace)))
     LEFT JOIN pg_namespace objsynschema ON ((objsynschema.oid = objsyn.synnamespace)));


ALTER TABLE sys.dba_policies OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6383 (class 1259 OID 14815)
-- Name: dba_profiles; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_profiles AS
 SELECT (
        CASE
            WHEN (ep.prfname = 'default'::name) THEN 'DEFAULT'::text
            ELSE quote_ident_redwood((ep.prfname)::text)
        END)::character varying(128) AS profile,
    (ep.rname)::character varying(32) AS resource_name,
    'PASSWORD'::character varying(8) AS resource_type,
    (ep.rvalue)::character varying(128) AS "limit",
    (
        CASE
            WHEN (ep.prfname = 'default'::name) THEN 'NO'::text
            ELSE 'YES'::text
        END)::character varying(3) AS common
   FROM ( WITH cte_profile AS (
                 SELECT edb_profile.oid,
                    edb_profile.prfname,
                    edb_profile.prffailedloginattempts,
                    edb_profile.prfpasswordlocktime,
                    edb_profile.prfpasswordlifetime,
                    edb_profile.prfpasswordgracetime,
                    edb_profile.prfpasswordreusetime,
                    edb_profile.prfpasswordreusemax,
                    edb_profile.prfpasswordverifyfuncdb,
                    edb_profile.prfpasswordverifyfunc
                   FROM edb_profile
                )
         SELECT cte_profile.oid,
            cte_profile.prfname,
            'FAILED_LOGIN_ATTEMPTS'::text AS rname,
                CASE
                    WHEN (cte_profile.prffailedloginattempts = '-2'::integer) THEN 'UNLIMITED'::text
                    WHEN (cte_profile.prffailedloginattempts = '-1'::integer) THEN 'DEFAULT'::text
                    ELSE (cte_profile.prffailedloginattempts)::text
                END AS rvalue
           FROM cte_profile
        UNION ALL
         SELECT cte_profile.oid,
            cte_profile.prfname,
            'PASSWORD_LOCK_TIME'::text,
                CASE
                    WHEN (cte_profile.prfpasswordlocktime = '-2'::integer) THEN 'UNLIMITED'::character varying
                    WHEN (cte_profile.prfpasswordlocktime = '-1'::integer) THEN 'DEFAULT'::character varying
                    ELSE nvl((rtrim(btrim((trunc(((cte_profile.prfpasswordlocktime)::numeric / 86400.0), 4))::text, '0'::text), '.'::text))::character varying, '0'::character varying)
                END AS nvl
           FROM cte_profile
        UNION ALL
         SELECT cte_profile.oid,
            cte_profile.prfname,
            'PASSWORD_LIFE_TIME'::text,
                CASE
                    WHEN (cte_profile.prfpasswordlifetime = '-2'::integer) THEN 'UNLIMITED'::character varying
                    WHEN (cte_profile.prfpasswordlifetime = '-1'::integer) THEN 'DEFAULT'::character varying
                    ELSE nvl((rtrim(btrim((trunc(((cte_profile.prfpasswordlifetime)::numeric / 86400.0), 4))::text, '0'::text), '.'::text))::character varying, '0'::character varying)
                END AS nvl
           FROM cte_profile
        UNION ALL
         SELECT cte_profile.oid,
            cte_profile.prfname,
            'PASSWORD_GRACE_TIME'::text,
                CASE
                    WHEN (cte_profile.prfpasswordgracetime = '-2'::integer) THEN 'UNLIMITED'::character varying
                    WHEN (cte_profile.prfpasswordgracetime = '-1'::integer) THEN 'DEFAULT'::character varying
                    ELSE nvl((rtrim(btrim((trunc(((cte_profile.prfpasswordgracetime)::numeric / 86400.0), 4))::text, '0'::text), '.'::text))::character varying, '0'::character varying)
                END AS nvl
           FROM cte_profile
        UNION ALL
         SELECT cte_profile.oid,
            cte_profile.prfname,
            'PASSWORD_REUSE_TIME'::text,
                CASE
                    WHEN (cte_profile.prfpasswordreusetime = '-2'::integer) THEN 'UNLIMITED'::character varying
                    WHEN (cte_profile.prfpasswordreusetime = '-1'::integer) THEN 'DEFAULT'::character varying
                    ELSE nvl((rtrim(btrim((trunc(((cte_profile.prfpasswordreusetime)::numeric / 86400.0), 4))::text, '0'::text), '.'::text))::character varying, '0'::character varying)
                END AS nvl
           FROM cte_profile
        UNION ALL
         SELECT cte_profile.oid,
            cte_profile.prfname,
            'PASSWORD_REUSE_MAX'::text,
                CASE
                    WHEN (cte_profile.prfpasswordreusemax = '-2'::integer) THEN 'UNLIMITED'::text
                    WHEN (cte_profile.prfpasswordreusemax = '-1'::integer) THEN 'DEFAULT'::text
                    ELSE (cte_profile.prfpasswordreusemax)::text
                END AS prfpasswordreusemax
           FROM cte_profile
        UNION ALL
         SELECT cte_profile.oid,
            cte_profile.prfname,
            'PASSWORD_VERIFY_FUNCTION'::text,
                CASE
                    WHEN (cte_profile.prfpasswordverifyfunc IS NULL) THEN 'NULL'::text
                    WHEN (cte_profile.prfpasswordverifyfunc = (0)::oid) THEN 'DEFAULT'::text
                    WHEN (cte_profile.prfpasswordverifyfuncdb <> ( SELECT pg_database.oid
                       FROM pg_database
                      WHERE (pg_database.datname = current_database()))) THEN '<FUNCTION_FROM_OTHER_DATABASE>'::text
                    ELSE ( SELECT quote_ident_redwood((f.proname)::text) AS quote_ident_redwood
                       FROM pg_proc f
                      WHERE (f.oid = cte_profile.prfpasswordverifyfunc))
                END AS quote_ident_redwood
           FROM cte_profile
  ORDER BY 1, 2, 3) ep;


ALTER TABLE sys.dba_profiles OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6452 (class 1259 OID 15138)
-- Name: dba_queue_tables; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_queue_tables AS
 SELECT quote_ident_redwood(((pg_get_userbyid(c.relowner))::character varying)::text) AS owner,
    quote_ident_redwood((qt.qtname)::text) AS queue_table,
        CASE
            WHEN (t.typname IS NULL) THEN 'RAW'::character varying
            ELSE 'OBJECT'::character varying
        END AS type,
    ((quote_ident_redwood((n.nspname)::text) || '.'::text) || quote_ident_redwood((t.typname)::text)) AS object_type,
        CASE qt.qtsort
            WHEN 'p'::"char" THEN 'PRIORITY'::character varying
            WHEN 'e'::"char" THEN 'ENQUEUE_TIME'::character varying
            WHEN 'P'::"char" THEN 'PRIORITY, ENQUEUE_TIME'::character varying
            WHEN 'E'::"char" THEN 'ENQUEUE_TIME, PRIORITY'::character varying
            ELSE 'NONE'::character varying
        END AS sort_order,
        CASE
            WHEN qt.qtmultiple_consumers THEN 'MULTIPLE'::character varying
            ELSE 'SINGLE'::character varying
        END AS recipients,
        CASE
            WHEN (qt.qtmessage_grouping = 0) THEN 'NONE'::character varying
            ELSE 'TRANSACTIONAL'::character varying
        END AS message_grouping,
    '9.6.0.0'::character varying AS compatible,
    (0)::numeric AS primary_instance,
    (0)::numeric AS secondary_instance,
    (1)::numeric AS owner_instance,
    ( SELECT (pg_description.description)::character varying AS description
           FROM pg_description
          WHERE ((pg_description.objoid = qt.oid) AND (pg_description.classoid = ('edb_queue_table'::regclass)::oid))) AS user_comment,
    'NO'::character varying AS secure
   FROM (((edb_queue_table qt
     LEFT JOIN pg_class c ON ((c.oid = qt.qtrelid)))
     LEFT JOIN pg_namespace n ON ((n.oid = c.relnamespace)))
     LEFT JOIN pg_type t ON ((t.oid = qt.qpayloadtype)));


ALTER TABLE sys.dba_queue_tables OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6455 (class 1259 OID 15152)
-- Name: dba_queues; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_queues AS
 SELECT quote_ident_redwood(((pg_get_userbyid(c.relowner))::character varying)::text) AS owner,
    quote_ident_redwood((q.aqname)::text) AS name,
    quote_ident_redwood((qt.qtname)::text) AS queue_table,
    q.oid AS qid,
        CASE q.aqtype
            WHEN 'e'::"char" THEN 'EXCEPTION_QUEUE'::character varying
            WHEN 'q'::"char" THEN 'NORMAL_QUEUE'::character varying
            ELSE NULL::character varying
        END AS queue_type,
    (q.aqretries)::numeric AS max_retries,
    (q.aqretrydelay)::numeric AS retry_delay,
        CASE
            WHEN q.aqcanenqueue THEN 'YES'::character varying
            ELSE 'NO'::character varying
        END AS enqueue_enabled,
        CASE
            WHEN q.aqcandequeue THEN 'YES'::character varying
            ELSE 'NO'::character varying
        END AS dequeue_enabled,
        CASE
            WHEN (q.aqretention = ('-1'::integer)::double precision) THEN 'FOREVER'::character varying
            ELSE (q.aqretention)::character varying
        END AS retention,
    ( SELECT (pg_description.description)::character varying AS description
           FROM pg_description
          WHERE ((pg_description.objoid = q.oid) AND (pg_description.classoid = ('edb_queue'::regclass)::oid))) AS user_comment,
    NULL::character varying AS network_name,
    'FALSE'::character varying AS sharded
   FROM ((edb_queue q
     LEFT JOIN pg_class c ON ((c.oid = q.aqrelid)))
     LEFT JOIN edb_queue_table qt ON ((qt.qtrelid = q.aqrelid)));


