--
-- TOC entry 6421 (class 1259 OID 14992)
-- Name: dba_role_privs; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_role_privs AS
 SELECT quote_ident_redwood((a.rolname)::text) AS grantee,
    quote_ident_redwood((b.rolname)::text) AS granted_role,
        CASE
            WHEN am.admin_option THEN 'YES'::text
            ELSE 'NO'::text
        END AS admin_option,
        CASE
            WHEN a.rolinherit THEN 'YES'::text
            ELSE 'NO'::text
        END AS default_role
   FROM ((pg_roles a
     JOIN pg_auth_members am ON ((am.member = a.oid)))
     JOIN pg_roles b ON ((b.oid = am.roleid)))
  WHERE a.rolcanlogin;


