--
-- TOC entry 6458 (class 1259 OID 15167)
-- Name: dba_source; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_source AS
 SELECT quote_ident_redwood((u.rolname)::text) AS owner,
    quote_ident_redwood((n.nspname)::text) AS schema_name,
    quote_ident_redwood((p.proname)::text) AS name,
        CASE
            WHEN (p.protype = '0'::"char") THEN 'FUNCTION'::text
            ELSE 'PROCEDURE'::text
        END AS type,
    (p.lt).line AS line,
    (p.lt).text AS text
   FROM ((( SELECT pg_proc.proname,
            pg_proc.pronamespace,
            pg_proc.proowner,
            pg_proc.protype,
            pg_proc.prorettype,
            pg_proc.proargtypes,
            pg_proc.proisagg,
            split_to_lines(edb_get_functiondef(pg_proc.oid)) AS lt
           FROM pg_proc
          WHERE (pg_proc.protype = ANY (ARRAY['0'::"char", '1'::"char"]))) p
     JOIN pg_namespace n ON ((n.oid = p.pronamespace)))
     JOIN pg_authid u ON ((u.oid = p.proowner)))
  WHERE ((n.nspparent = (0)::oid) AND (p.prorettype <> ('cstring'::regtype)::oid) AND ((p.proargtypes[0] IS NULL) OR (p.proargtypes[0] <> ('cstring'::regtype)::oid)) AND (NOT p.proisagg))
UNION ALL
 SELECT quote_ident_redwood((u.rolname)::text) AS owner,
    quote_ident_redwood((s.nspname)::text) AS schema_name,
    quote_ident_redwood((n.nspname)::text) AS name,
    'PACKAGE'::text AS type,
    (n.lt).line AS line,
    (n.lt).text AS text
   FROM ((( SELECT pg_namespace.nspname,
            pg_namespace.nspowner,
            pg_namespace.nspparent,
            split_to_lines(edb_get_packageheaddef(pg_namespace.oid)) AS lt
           FROM pg_namespace
          WHERE ((pg_namespace.nspparent <> (0)::oid) AND (pg_namespace.nspobjecttype = (0)::oid))) n
     JOIN pg_namespace s ON ((s.oid = n.nspparent)))
     JOIN pg_authid u ON ((u.oid = n.nspowner)))
UNION ALL
 SELECT quote_ident_redwood((u.rolname)::text) AS owner,
    quote_ident_redwood((s.nspname)::text) AS schema_name,
    quote_ident_redwood((n.nspname)::text) AS name,
    'PACKAGE BODY'::text AS type,
    (n.lt).line AS line,
    (n.lt).text AS text
   FROM ((( SELECT pg_namespace.nspname,
            pg_namespace.nspowner,
            pg_namespace.nspparent,
            split_to_lines(edb_get_packagebodydef(pg_namespace.oid)) AS lt
           FROM pg_namespace
          WHERE ((pg_namespace.nspparent <> (0)::oid) AND (pg_namespace.nspobjecttype = (0)::oid) AND (pg_namespace.nspbodysrc IS NOT NULL))) n
     JOIN pg_namespace s ON ((s.oid = n.nspparent)))
     JOIN pg_authid u ON ((u.oid = n.nspowner)))
UNION ALL
 SELECT quote_ident_redwood((u.rolname)::text) AS owner,
    quote_ident_redwood((s.nspname)::text) AS schema_name,
    quote_ident_redwood((n.nspname)::text) AS name,
    'TYPE'::text AS type,
    (n.lt).line AS line,
    (n.lt).text AS text
   FROM ((( SELECT pg_namespace.nspname,
            pg_namespace.nspowner,
            pg_namespace.nspparent,
            split_to_lines(edb_get_objecttypeheaddef(pg_namespace.nspobjecttype)) AS lt
           FROM pg_namespace
          WHERE (pg_namespace.nspobjecttype <> (0)::oid)) n
     JOIN pg_namespace s ON ((s.oid = n.nspparent)))
     JOIN pg_authid u ON ((u.oid = n.nspowner)))
UNION ALL
 SELECT quote_ident_redwood((u.rolname)::text) AS owner,
    quote_ident_redwood((s.nspname)::text) AS schema_name,
    quote_ident_redwood((n.nspname)::text) AS name,
    'TYPE BODY'::text AS type,
    (n.lt).line AS line,
    (n.lt).text AS text
   FROM ((( SELECT pg_namespace.nspname,
            pg_namespace.nspowner,
            pg_namespace.nspparent,
            split_to_lines(edb_get_objecttypebodydef(pg_namespace.nspobjecttype)) AS lt
           FROM pg_namespace
          WHERE ((pg_namespace.nspobjecttype <> (0)::oid) AND (pg_namespace.nspbodysrc IS NOT NULL))) n
     JOIN pg_namespace s ON ((s.oid = n.nspparent)))
     JOIN pg_authid u ON ((u.oid = n.nspowner)))
UNION ALL
 SELECT quote_ident_redwood((u.rolname)::text) AS owner,
    quote_ident_redwood((n.nspname)::text) AS schema_name,
    quote_ident_redwood((p.tgname)::text) AS name,
    'TRIGGER'::text AS type,
    (p.lt).line AS line,
    (p.lt).text AS text
   FROM ((( SELECT t.tgname,
            c.relnamespace,
            c.relowner,
            split_to_lines(pg_get_triggerdef(t.oid)) AS lt
           FROM pg_trigger t,
            pg_class c
          WHERE (t.tgrelid = c.oid)) p
     JOIN pg_namespace n ON ((n.oid = p.relnamespace)))
     JOIN pg_authid u ON ((u.oid = p.relowner)));


