--
-- TOC entry 6449 (class 1259 OID 15124)
-- Name: dba_subpart_key_columns; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_subpart_key_columns AS
 SELECT quote_ident_redwood((pg_get_userbyid(s.relowner))::text) AS owner,
    quote_ident_redwood((s.rootschema)::text) AS schema_name,
    quote_ident_redwood((s.rootrelname)::text) AS name,
    'TABLE'::character(5) AS object_type,
    quote_ident_redwood((a.attname)::text) AS column_name,
    (s.ordinal + 1) AS column_position
   FROM (( SELECT pd.partrelid,
            pd.partattrs,
            generate_subscripts(pd.partattrs, 1) AS ordinal,
            ns.nspname AS rootschema,
            class.relname AS rootrelname,
            class.relowner
           FROM (((pg_partitioned_table pd
             JOIN pg_inherits pi ON ((pd.partrelid = pi.inhrelid)))
             JOIN pg_class class ON ((pi.inhparent = class.oid)))
             JOIN pg_namespace ns ON ((ns.oid = class.relnamespace)))
          WHERE ((class.relkind = 'p'::"char") AND (class.relispartition = false))) s
     JOIN pg_attribute a ON (((a.attrelid = s.partrelid) AND (a.attnum = s.partattrs[s.ordinal]))))
  GROUP BY (quote_ident_redwood((pg_get_userbyid(s.relowner))::text)), (quote_ident_redwood((s.rootschema)::text)), (quote_ident_redwood((s.rootrelname)::text)), ('TABLE'::character(5)), (quote_ident_redwood((a.attname)::text)), (s.ordinal + 1)
  ORDER BY (quote_ident_redwood((s.rootrelname)::text)), (s.ordinal + 1);


ALTER TABLE sys.dba_subpart_key_columns OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6396 (class 1259 OID 14876)
-- Name: dba_view_columns; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dba_view_columns AS
 SELECT (quote_ident_redwood((isc.owner)::text))::character varying AS owner,
    (quote_ident_redwood((isc.schema_name)::text))::character varying AS schema_name,
    (quote_ident_redwood((isc.table_name)::text))::character varying AS view_name,
    (quote_ident_redwood((isc.column_name)::text))::character varying AS column_name,
        DECODE(  (isc.data_type)::character varying
            , ('interval'::text)::character varying
            , ('INTERVAL'::text)::character varying
            , ('timestamp with time zone'::text)::character varying
            , ('TIMESTAMP WITH TIME ZONE'::text)::character varying
            , ('time with time zone'::text)::character varying
            , ('TIME WITH TIME ZONE'::text)::character varying
            , ('bigint'::text)::character varying
            , ('BIGINT'::text)::character varying
            , ('character varying'::text)::character varying
            , ('VARCHAR2'::text)::character varying
            , ('boolean'::text)::character varying
            , ('BOOLEAN'::text)::character varying
            , ('smallint'::text)::character varying
            , ('SMALLINT'::text)::character varying
            , ('double precision'::text)::character varying
            , ('DOUBLE PRECISION'::text)::character varying
            , ('integer'::text)::character varying
            , ('INTEGER'::text)::character varying
            , ('character'::text)::character varying
            , ('CHAR'::text)::character varying
            , ('timestamp without time zone'::text)::character varying
            , ('DATE'::text)::character varying
            , ('time without time zone'::text)::character varying
            , ('TIME WITHOUT TIME ZONE'::text)::character varying
            , ('real'::text)::character varying
            , ('REAL'::text)::character varying
            , ('numeric'::text)::character varying
            , ('NUMBER'::text)::character varying
            , ('bit'::text)::character varying
            , ('BIT'::text)::character varying
            , ('time'::text)::character varying
            , ('TIME'::text)::character varying
            , ('bit varying'::text)::character varying
            , ('BIT VARYING'::text)::character varying
            , ('BYTEA'::text)::character varying
            , ('BLOB'::text)::character varying
            , ('TEXT'::text)::character varying
            , ('CLOB'::text)::character varying
            , (isc.data_type)::character varying
        ) AS data_type,
    (isc.data_length)::numeric AS data_length,
    (isc.data_precision)::numeric AS data_precision,
    (isc.data_scale)::numeric AS data_scale,
    isc.nullable,
    (isc.column_id)::numeric AS column_id,
    (isc.data_default)::character varying AS data_default
   FROM ( SELECT pg_get_userbyid(c.relowner) AS owner,
            nc.nspname AS schema_name,
            c.relname AS table_name,
            a.attname AS column_name,
                CASE
                    WHEN (t.typtype = 'd'::"char") THEN
                    CASE
                        WHEN ((bt.typelem <> (0)::oid) AND (bt.typlen = '-1'::integer)) THEN 'ARRAY'::text
                        ELSE
                        CASE
                            WHEN (quote_ident(format_type(t.typbasetype, NULL::integer)) = format_type(t.typbasetype, NULL::integer)) THEN quote_ident_redwood(format_type(t.typbasetype, NULL::integer))
                            ELSE format_type(t.typbasetype, NULL::integer)
                        END
                    END
                    ELSE
                    CASE
                        WHEN ((t.typelem <> (0)::oid) AND (t.typlen = '-1'::integer)) THEN 'ARRAY'::text
                        ELSE
                        CASE
                            WHEN (quote_ident(format_type(a.atttypid, NULL::integer)) = format_type(a.atttypid, NULL::integer)) THEN quote_ident_redwood(format_type(a.atttypid, NULL::integer))
                            ELSE format_type(a.atttypid, NULL::integer)
                        END
                    END
                END AS data_type,
            information_schema._pg_char_max_length(information_schema._pg_truetypid(a.*, t.*), information_schema._pg_truetypmod(a.*, t.*)) AS data_length,
            information_schema._pg_numeric_precision(information_schema._pg_truetypid(a.*, t.*), information_schema._pg_truetypmod(a.*, t.*)) AS data_precision,
            information_schema._pg_numeric_scale(information_schema._pg_truetypid(a.*, t.*), information_schema._pg_truetypmod(a.*, t.*)) AS data_scale,
            a.attnum AS column_id,
                CASE
                    WHEN (a.attnotnull OR ((t.typtype = 'd'::"char") AND t.typnotnull)) THEN 'N'::character(1)
                    ELSE 'Y'::character(1)
                END AS nullable,
            pg_get_expr(ad.adbin, ad.adrelid) AS data_default
           FROM (((((pg_attribute a
             LEFT JOIN pg_attrdef ad ON (((a.attrelid = ad.adrelid) AND (a.attnum = ad.adnum))))
             JOIN (pg_class c
             JOIN pg_namespace nc ON ((c.relnamespace = nc.oid))) ON ((a.attrelid = c.oid)))
             JOIN (pg_type t
             JOIN pg_namespace nt ON ((t.typnamespace = nt.oid))) ON ((a.atttypid = t.oid)))
             LEFT JOIN (pg_type bt
             JOIN pg_namespace nbt ON ((bt.typnamespace = nbt.oid))) ON (((t.typtype = 'd'::"char") AND (t.typbasetype = bt.oid))))
             LEFT JOIN (pg_collation co
             JOIN pg_namespace nco ON ((co.collnamespace = nco.oid))) ON (((a.attcollation = co.oid) AND ((nco.nspname <> 'pg_catalog'::name) OR (co.collname <> 'default'::name)))))
          WHERE ((NOT pg_is_other_temp_schema(nc.oid)) AND (a.attnum > 0) AND (NOT a.attisdropped) AND (c.relkind = 'v'::"char"))) isc
  ORDER BY (quote_ident_redwood((isc.owner)::text))::character varying, (quote_ident_redwood((isc.schema_name)::text))::character varying;


