 SELECT _dbms_aq_stat_messages.schema_name,
    _dbms_aq_stat_messages.queue_name,
    _dbms_aq_stat_messages.ready,
    _dbms_aq_stat_messages.waiting,
    _dbms_aq_stat_messages.processed,
    _dbms_aq_stat_messages.expired
   FROM _dbms_aq_stat_messages() _dbms_aq_stat_messages(schema_name, queue_name, ready, waiting, processed, expired);


ALTER TABLE sys.dbms_aq_stat_messages OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6361 (class 1259 OID 14383)
-- Name: dbms_aq_stat_queues; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dbms_aq_stat_queues AS
 SELECT n.nspname AS schema,
    q.aqname AS queue,
    s.callbacks,
    s.retry,
    s.timed_event,
    s.next_event_time
   FROM ((edb_queue q
     JOIN _dbms_aq_stat_queues() s(queue_oid, callbacks, retry, timed_event, next_event_time) ON ((s.queue_oid = q.oid)))
     JOIN pg_namespace n ON ((q.aqnamespace = n.oid)));


ALTER TABLE sys.dbms_aq_stat_queues OWNER TO "mdt-mdm-edb-cjm-prd";

--
-- TOC entry 6363 (class 1259 OID 14392)
-- Name: dbms_aq_stat_waiters; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.dbms_aq_stat_waiters AS
 SELECT s.backend_pid,
    d.datname AS database,
    n.nspname AS schema,
    q.aqname AS queue
   FROM (((_dbms_aq_stat_waiters() s(backend_pid, db_oid, queue_oid)
     JOIN pg_database d ON ((s.db_oid = d.oid)))
     LEFT JOIN edb_queue q ON ((s.queue_oid = q.oid)))
     LEFT JOIN pg_namespace n ON ((q.aqnamespace = n.oid)));


ALTER TABLE sys.dbms_aq_stat_waiters OWNER TO "mdt-mdm-edb-cjm-prd";

