-- Name: user_db_links; Type: VIEW; Schema: sys; Owner: mdt-mdm-edb-cjm-prd
--

CREATE VIEW sys.user_db_links AS
 SELECT upper((e.lnkname)::text) AS db_link,
        DECODE(  ((e.lnktype)::text)::character varying
            , ('0'::text)::character varying
            , ('REDWOOD'::text)::character varying
            , ('1'::text)::character varying
            , ('EDB'::text)::character varying
            , NULL::character varying
        ) AS type,
    quote_ident_redwood(e.lnkuser) AS username,
    e.lnkpassword AS password,
    e.lnkconnstr AS host
   FROM edb_dblink e
  WHERE ((pg_get_userbyid(e.lnkowner) = "current_user"()) AND (e.lnkispublic = false));


