--

CREATE VIEW sys."v$version" AS
 SELECT 'Oracle Database 10g Edition Release 10.2.0.1.0 - Product is similar'::text AS banner
   FROM pg_settings
  WHERE (pg_settings.name = 'server_version'::text)
UNION ALL
 SELECT 'PL/SQL Release 10.2.0.1.0 - Production is similar'::text AS banner
   FROM pg_settings
  WHERE (pg_settings.name = 'server_version'::text)
UNION ALL
 SELECT 'CORE 10.2.0.1.0 Production is similar'::text AS banner
   FROM pg_settings
  WHERE (pg_settings.name = 'server_version'::text);


ALTER TABLE sys."v$version" OWNER TO "mdt-mdm-edb-cjm-prd";

